'use strict';
(globalThis.ABBATE_QUESTION_TRANSLATIONS||(globalThis.ABBATE_QUESTION_TRANSLATIONS={}))["sk"]={"g-flurpruefung":["Čo zahŕňa vizuálna a funkčná kontrola pred začatím práce?","Pred prvou misiou dňa.","Skontrolujte iba hladinu paliva a farbu vozidla.","Skontrolujte brzdy, riadenie, vidlice, pneumatiky a bezpečnostné zariadenia podľa návodu na obsluhu.","Vykonajte skúšobnú jazdu so zdvihnutým nákladom.","Denná kontrola zahŕňa bezpečnostné časti a funkcie podľa návodu na obsluhu."],"g-rueckhalt":["Ako sa vysporiadate s existujúcim zádržným systémom vodiča?","Vysokozdvižný vozík má povinný záchytný systém.","Používajte ho správne počas jazdy.","Používajte len na nerovné podlahy.","Pri krátkych cestách ho deaktivujte.","Zamýšľané zadržiavacie systémy sa musia používať v súlade s pokynmi výrobcu; poskytujú osobitnú ochranu v prípade prevrátenia."],"g-mangelmelden":["Čo platí pre vysokozdvižný vozík s poškodenou vidlicou?","Pri kontrole si všimnete zreteľne ohnutý hrot.","Ak je to možné, rozložte záťaž na druhý hrot.","Do nasledujúceho servisu jazdite len s ľahkým nákladom.","Vysokozdvižný vozík nepoužívajte a závadu nahláste zodpovednej osobe.","Poškodené zariadenie na manipuláciu s nákladom môže zlyhať; Poruchy súvisiace s bezpečnosťou vyžadujú odstavenie, kým sa neobjasnia."],"g-einweisung":["Prechádzate na vysokozdvižný vozík s rôznymi ovládacími prvkami. Čo je potrebné pred použitím?","Prevádzka sa líši od vášho predchádzajúceho vozidla.","Pokyny týkajúce sa zariadenia a dodržiavanie návodu na obsluhu.","Vždy stačí krátke vysvetlenie od nezúčastneného kolegu.","Žiadne ďalšie informácie, ak máte licenciu na vysokozdvižný vozík.","Všeobecná kvalifikácia nenahrádza potrebné poučenie o skutočne používanom zariadení."],"g-anbaugeraet":["Mali by ste použiť prílohu. Čo skontrolujete ako prvé?","Nové zariadenie mení spôsob zdvíhania nákladu.","Či prídavné zariadenie vyhovuje schváleniu vozidla a prípustnému zaťaženiu.","Iba to, či je možné zariadenie pripevniť vizuálne.","Či je možné nainštalovať prílohu bez dokumentácie.","Prídavné zariadenia môžu zmeniť zostávajúcu nosnosť a ťažisko nákladu; Schválenia a informácie o nosnosti sa musia skontrolovať."],"g-diagramm":["Prečo potrebujete diagram nosnosti?","Ťažké bremeno je prítomné s ťažiskom ďaleko smerom von.","Na určenie najkratšej trasy.","Na posúdenie maximálneho povoleného zaťaženia v závislosti od výšky zdvihu a ťažiska bremena.","Na určenie kapacity nádrže.","Prípustné zaťaženia závisia okrem iného od vzdialenosti ťažiska bremena a výšky zdvihu."],"g-lastschwerpunkt":["Čo sa zvyčajne stane, keď sa ťažisko posunie ďalej dopredu?","Dlhý náklad vyčnieva ďaleko pred vidlice.","Prípustná nosnosť sa môže znížiť.","Nosnosť sa neustále zvyšuje.","Vzdialenosť nemá vplyv na klopný moment.","Väčšia vzdialenosť od ťažiska nákladu zvyšuje klopný moment a môže znížiť prípustnú nosnosť."],"g-gabelabstand":["Ako by mali vidlice vyzdvihnúť vhodnú paletu?","Chcete vyzdvihnúť rovnomerne naloženú paletu.","S hrotmi čo najbližšie a len na jednom rohu.","S takou veľkou vzdialenosťou, že sa paleta prevráti na stranu.","S vhodnou vzdialenosťou medzi prstami a dostatočnou plochou podvozku a podpory.","Náklad musí byť bezpečne a čo najrovnomernejšie podopretý cez vidlice."],"g-schieflast":["Náklad je naskladaný nestabilne. čo je správne?","Kartónové krabice môžu pri zdvíhaní spadnúť.","Začnite pomaly; náboj sa sám stabilizuje.","Pred zdvihnutím nákladu ho dostatočne zaistite alebo ho nechajte znovu zložiť.","Zdvihnite náklad nad výšku hlavy, aby neprekážal.","Voľný alebo nestabilný náklad môže spadnúť a ohroziť ľudí; najprv vykonajte bezpečnostné opatrenia."],"g-personen":["Dá sa človek zdvihnúť na bežné vidly?","Kolega chce dosiahnuť svetlo.","Áno, ak kolega nosí prilbu.","Nie, osoby môžu používať iba určené a povolené zariadenia v súlade so špeciálnymi požiadavkami.","Áno, ak sa priblížite len na malú výšku.","Normálne vidlice nie sú osobnou pracovnou plošinou; Preprava a zdvíhanie osôb podlieha špeciálnym požiadavkám."],"g-transporthoehe":["Ako zvyčajne prepravujete paletu?","Cesta je čistá a rovná.","So zdvihnutým bremenom len do potrebnej miery a v súlade s návodom na obsluhu.","S nákladom zdvihnutým čo najvyššie, aby bolo lepšie vidieť.","So zdvíhacím stožiarom silne nakloneným dopredu, bez ohľadu na zaťaženie.","Nízka prepravná poloha znižuje riziko prevrátenia a kolízie; Rozhodujúce sú pokyny k zariadeniu."],"g-kurvenfahrt":["Prečo je rýchle prechádzanie zákrutou s vysokozdvižným vozíkom nebezpečné?","Chcete rýchlo opustiť úzku cestu.","Pretože len rýchlejšie vybíja batériu.","Pretože vysokozdvižný vozík sa automaticky lepšie riadi.","Bočné sily totiž ovplyvňujú stabilitu a môžu viesť k prevráteniu.","V zákrutách vstupujú do hry dodatočné sily; rýchlosť musí byť prispôsobená zaťaženiu a podmienkam."],"g-ladebruecke":["Čo kontrolujete pred jazdou na nakladací most?","Mali by ste jazdiť v kamióne.","Len či cesta vyzerá dostatočne široká.","Nosnosť, bezpečná podpora a ochrana proti posunutiu ako aj zabezpečenie vozidla.","Len či je zapnuté osvetlenie.","Nakladacie mostíky a vozidlá musia byť zabezpečené proti pohybu a vhodné pre náklad."],"g-fussgaenger":["Ako sa správate na neprehľadnej križovatke s chodcami?","Vizuálne spojenia sú obmedzené.","Jazdite primeranou rýchlosťou, v prípade potreby zastavte a zabezpečte bezpečnú viditeľnosť.","Pri prenášaní nákladu si vždy nárokujte prednosť v jazde.","Stačí zatrúbiť a pokračovať v jazde.","Chodci majú osobitné potreby ochrany; Rýchlosť, viditeľnosť a komunikácia musia byť prispôsobené dopravnej ceste."],"g-batterieladen":["Na čo si dať pri nabíjaní pohonnej batérie obzvlášť pozor?","Používa sa nabíjacia stanica batérie.","Miesto nabíjania je možné zvoliť bez ohľadu na pokyny výrobcu.","Otvorený oheň je povolený, pokiaľ vozík stojí.","Vhodná ložná plocha, dostatočné vetranie a špecifikácie výrobcu, ako aj ochrana proti požiaru a výbuchu.","Pri nabíjaní môžu vzniknúť nebezpečenstvá spôsobené elektrickou energiou, plynmi a chemikáliami; je potrebné dodržiavať stanovené ochranné opatrenia."],"h-beauftragt":["Za akých podmienok môžete samostatne obsluhovať zdvíhaciu plošinu?","Vo firme by ste mali používať pracovnú plošinu.","Ak máte vodičský preukaz na auto.","Ak ste vhodný, poučený alebo kvalifikovaný a poverený zamestnávateľom.","Ak ste niekedy videli pracovnú plošinu.","Zamestnávateľ musí zabezpečiť spôsobilosť, kvalifikáciu a úlohy v súlade s prevádzkovými požiadavkami."],"h-vorpruefung":["Čo je potrebné skontrolovať pred začatím práce s pracovnou plošinou?","Pódium bolo cez noc vonku.","Vizuálna a funkčná skúška podľa pokynov výrobcu vrátane bezpečnostných zariadení.","Len farba a vek javiska.","Či už je pracovný materiál na plošine.","Pred použitím je potrebné skontrolovať stroj, ovládacie prvky, núdzové funkcie a viditeľné poškodenia podľa návodu na obsluhu."],"h-tragfaehigkeit":["Aké informácie určujú prípustné zaťaženie pracovného koša?","Dvaja ľudia by si so sebou chceli vziať ďalšie nástroje.","Ľudia môžu voľne odhadnúť prípustnú celkovú hmotnosť.","Počíta sa len váha najťažšieho človeka.","Nesmie byť prekročená špecifikácia nosnosti pre osoby, náradie a materiál.","Menovité zaťaženie sa vzťahuje na celkové povolené zaťaženie vrátane akéhokoľvek prepravovaného materiálu."],"h-untergrund":["Čo zvažujete pred postavením pódia s podperami?","Pracujete v blízkosti vyplnenej oblasti.","Len v dosahu výložníka.","Skontrolujte nosnosť a rovnosť podkladu ako aj vhodnú podperu podľa návodu.","Na čo najnižšom počte vysunutých podpier.","Nedostatočná pôda alebo nesprávna podpora môžu viesť k strate stability."],"h-wind":["Fúka silný vietor. Ako na to?","Ocitnete sa s vonkajším javiskom.","Dodržiavajte limity výrobcu a ak ich prekročíte, zastavte prevádzku alebo bezpečne spustite kôš.","Vysuňte plošinu čo najviac, aby bola stabilnejšia.","Reagujte len vtedy, ak padnú voľné predmety.","Veterné podmienky povolené výrobcom sú prevádzkové limity; Vietor môže vytvárať nebezpečné dodatočné sily."],"h-strom":["Musíte pracovať v blízkosti nadzemného elektrického vedenia. Čo je rozhodujúce?","V pracovnej oblasti je živé vedenie.","Prilba nahrádza udržiavanie bezpečnej vzdialenosti.","Stačí izolovať kôš a pracovať bez koordinácie.","Objasnite nebezpečnú oblasť a zabezpečte potrebné ochranné vzdialenosti alebo iné vhodné opatrenia.","Elektrický preskok je možný aj bez priameho kontaktu; Pred začatím prevádzky sa musia určiť potrebné ochranné opatrenia."],"h-notablass":["Prečo je potrebné poznať postup núdzového spúšťania?","Je možné zlyhanie normálneho ovládania.","Aby v prípade poruchy bola možná bezpečná záchrana podľa prístroja.","Aby zariadenie bežalo rýchlejšie v bežnej prevádzke.","Nahradiť pravidelné testovanie.","Pred použitím musia byť známe a funkčné núdzové ovládacie prvky, núdzové spúšťanie a záchranné koncepty."],"h-gelaender":["Ako dosiahnete dodatočnú výšku v pracovnom koši?","Miesto montáže je mimo vášho dosahu.","Vylezte na plot koša.","Na zábradlie položte dosku.","Použite vhodnú plošinu s dostatočnou pracovnou výškou; nelezte na zábradlie.","Preliezanie plota alebo improvizované vyvýšenia ohrozujú ochranu proti pádu."],"h-psaga":["Aké požiadavky platia pre osobné ochranné prostriedky proti pádu?","Používate pracovnú plošinu, pre ktorú je k dispozícii záchytný systém.","Vždy postačuje akýkoľvek kotviaci bod mimo koša.","Dodržujte hodnotenie rizík, informácie výrobcu a vhodné kotviace body.","Ak má kôš zábradlie, nepoužívajte žiadne zabezpečenie.","O tom, či a aké OOPP sú potrebné, rozhoduje posúdenie rizík, výstavba etapy a návod na obsluhu."],"h-verfahren":["Je možné posunúť javisko so zdvihnutou plošinou?","Pracovisko je vzdialené pár metrov.","Iba ak to model a prevádzkové podmienky umožňujú podľa pokynov výrobcu.","Vždy, pokiaľ sa všetci držia.","Nie, nikdy bez ohľadu na dizajn a schválenie výrobcu.","Pohyb vo zdvihnutej polohe závisí od zariadenia a je povolený len v rámci schválených prevádzkových podmienok."],"h-kollision":["Čo je potrebné zorganizovať pri práci v blízkosti žeriavov alebo iných strojov?","Pohyblivé časti by sa mohli dostať do pracovného koša.","Nič; pracovný kôš je vždy viditeľný.","Pracovný kôš vždy prechádzajte cez ostatné stroje.","Koordinujte pracovné oblasti, aby ste predišli kolíziám alebo bodom zovretia.","Súbežná prevádzka stroja vyžaduje koordinované pracovné procesy a ochranu pred kolíziami alebo zaseknutím."],"h-einstieg":["Ako vstupujete alebo vystupujete z pracovného koša?","Dostanete sa do koša na úrovni zeme.","Prelezte cez vonkajšie zábradlie.","Cez určený prístup v bezpečnej polohe podľa návodu na obsluhu.","Cez rebrík umiestnený vedľa s vysunutým ramenom.","Je potrebné dodržiavať zamýšľaný prístup a pokyny výrobcu; Nekontrolované preliezanie predstavuje riziko pádu."],"h-defekt":["Zariadenie núdzového zastavenia nefunguje. čo to robíš?","Závadu zistíte pri obhliadke.","Platformu nepoužívajte a závadu nahláste.","Pokračujte v práci, ak fungujú normálne ovládacie prvky.","Prepínač prilepte páskou, aby ho nikto neovládal.","Porucha bezpečnostného zariadenia je bezpečnostne relevantnou chybou a bráni bezpečnej prevádzke."],"h-sicht":["Hnací pohyb nie je viditeľný kvôli prekážke. Ako na to idete?","Mali by ste presunúť mobilné pódium.","Jazdite pomaly bez viditeľnosti.","Stačí sa spoľahnúť na ukazovateľ vzdialenosti.","Zastavte pohyb a zabezpečte viditeľnosť alebo bezpečný pokyn podľa návodu na obsluhu.","Pred zákrokom musia byť ľudia, prekážky a dopravné cesty bezpečne preskúmané."],"h-rettung":["Čo zahŕňa plánovanie nasadenia pri práci vo väčších výškach?","Pódium sa používa v odľahlej oblasti.","Iba plánovaná dĺžka práce.","Vhodný záchranný koncept s prístupnými, vyškolenými osobami a postupmi núdzového spúšťania.","Predpoklad, že hasiči akýkoľvek problém okamžite vyriešia.","Účinná záchrana musí byť zorganizovaná vopred, aj keď bežné kontroly zlyhajú."],"k-befaehigung":["Čo je potrebné na samostatnú prevádzku žeriavu?","Žeriavnícke práce má prevziať nový zamestnanec.","Vhodnosť a požadovaná kvalifikácia, inštrukcie a zodpovedajúce zadanie.","Stačí vodičský preukaz na auto.","Pozerať raz stačí.","Žeriavnícke práce môžu byť zverené len kvalifikovaným a oprávneným osobám; Návod na vybavenie je súčasťou."],"k-funktionspruefung":["Čo je potrebné na kontrolu žeriavu pred začiatkom zmeny?","Prevezmete vnútorný žeriav.","Stačí si prečítať čas chodu na typovom štítku.","Skontrolujte bezpečnostne dôležité funkcie a viditeľné chyby podľa návodu na obsluhu.","Otestujte žeriav s maximálnym zaťažením bez kontroly.","Povinná prevádzková kontrola slúži na včasnú identifikáciu nebezpečných porúch."],"k-traglast":["Aký význam má prípustná nosnosť?","Je potrebné zdvihnúť bremeno.","Je to nezáväzné odporúčanie.","Platí to len vtedy, keď je hák úplne zasunutý.","Prípustná nosnosť pre príslušný prevádzkový stav nesmie byť prekročená.","Pre určité typy žeriavov môžu prípustné zaťaženia závisieť od polomeru, polohy výložníka a výzbroje."],"k-personen":["Čo platí pre ľudí pod zaveseným bremenom?","Náklad sa presúva cez pracovnú oblasť.","Nebezpečná oblasť musí byť voľná; nikto nesmie vstúpiť pod zavesené bremeno.","Prilba vám umožňuje zostať priamo pod ňou.","Krátke prejazdy sú povolené, ak sa žeriav pohybuje pomaly.","Zavesené bremená predstavujú riziko pádu a pomliaždenia; Ľudia sa musia držať mimo nebezpečnej oblasti."],"k-signale":["Nevidíte útočníka a dostávate protichodné signály. čo to robíš?","Komunikácia je nejasná.","Pokračujte posledným príkazom jazdy.","Zastavte pohyb a jasne vyjasnite komunikáciu.","Zložte záťaž rýchlejšie, bez konzultácie.","Bezpečné pohyby nákladu vyžadujú jasné signály a jasnú komunikáciu."],"k-sicht":["Kto poskytne podporu počas prepravy, ak operátor žeriavu úplne nevidí dráhu nákladu?","Chodbu zakrýva halový stĺp.","Osoba, ktorá náhodou prechádza okolo bez predchádzajúcej dohody.","Nikto; dôležitý je len háčik.","Vhodná, poučená osoba s jasne dohodnutým porozumením.","Ak dráha zaťaženia nie je viditeľná, je potrebný príslušný pokyn alebo iné bezpečné riešenie."],"k-ruck":["Prečo sa treba vyhýbať trhavým pohybom žeriavu?","Ťažký náklad sa začne hojdať.","Vytvárajú dodatočné dynamické napätia a môžu destabilizovať zaťaženie.","V podstate obmedzujú akýkoľvek pohyb kyvadla.","Vždy zvyšujú nominálnu nosnosť.","Akceleračné a brzdné sily zvyšujú zaťaženie žeriavu a popruhov."],"k-sperrbereich":["Čo by ste mali skontrolovať pred kývaním nákladu v spoločnej oblasti?","V blízkosti pracujú ďalší zamestnanci.","Či sa náklad vizuálne zhoduje so žeriavom.","Či je nebezpečný priestor zabezpečený a nie sú ohrození žiadni ľudia.","Či sa dá náklad vyniesť čo najvyššie nad všetkých.","Na otočnej dráhe a dráhe nákladu sa nesmú nachádzať nechránené osoby."],"k-stuetzen":["Čo je rozhodujúce pre mobilný žeriav s podperami?","Žeriav je postavený na čiastočne zaplnenej zemi.","Len na šírku cesty.","Farba nosných dosiek.","Nosná základňa, ako aj podpera a rozloženie zaťaženia podľa pokynov na inštaláciu a výrobcu.","Inštalácia má významný vplyv na stabilitu, najmä v meniacich sa pôdnych podmienkach."],"k-wetter":["Náraz vetra spôsobuje výrazné rozkývanie nákladu. čo je správne?","Pracujete vonku.","Bezpečne zastavte pohyb a dodržiavajte prípustné prevádzkové podmienky.","Rýchlo zrýchlite pohyb.","Pokračujte v zdvíhaní bremena napriek prekročeniu limitov výrobcu.","Vietor a kývavé pohyby môžu destabilizovať náklad a žeriav; Musia sa dodržiavať limity aplikácie."],"k-freileitung":["Čo platí pri používaní žeriavov v blízkosti nadzemných elektrických vedení?","Výložník alebo náklad sa môžu priblížiť k čiare.","Pri nevodivej záťaži nie sú vôle dôležité.","Pred začatím práce si so zodpovednými osobami vyjasnite nebezpečnú oblasť a potrebné ochranné opatrenia.","Spoľahnite sa len na vlastnú reakciu žeriavnika.","Existuje nebezpečenstvo spôsobené kontaktom a preskokom napätia; sú potrebné bezpečné ochranné vzdialenosti alebo iné opatrenia."],"k-sichern":["Čo robíte predtým, ako opustíte žeriav?","Práca je prerušená.","Nechajte náklad visieť zavesený.","Nechajte žeriav bez dozoru s pohonom v chode.","Bezpečne spustite bremeno a zaistite žeriav podľa návodu na obsluhu.","Zavesené bremená nesmú zostať nekontrolované; Žeriav a náklad musia byť bezpečne zaparkované."],"k-lastanschlag":["Ako viete, či je použitý popruh vhodný?","Náklad by sa mal zdvíhať pomocou zdvíhacieho popruhu.","Z hľadiska značenia, nosnosti, stavu a vhodnosti pre typ nástavca.","Už len podľa farby zdvíhacieho popruhu.","Pretože to bolo použité už včera.","Nosnosť a stav musia byť dostatočné s prihliadnutím na podmienky pripevnenia."],"k-stopp":["Do dráhy nákladu nečakane vstúpi osoba. čo to robíš?","Žeriav momentálne presúva náklad.","Okamžite bezpečne zastavte pohyb a nechajte nebezpečné miesto vyčistiť.","Stačí dať varovný signál a pokračovať v jazde.","Zdvihnite náklad vyššie a prejdite po ňom.","Ľudia musia byť chránení pred pohybmi nákladu; Ak hrozí bezprostredné nebezpečenstvo, pohyb treba zastaviť."],"k-neuerkran":["Dostanete žeriav s neznámym ovládaním. čo je správne?","Ovládanie je iné ako doteraz.","Ak máte podozrenie, skúste bežné klávesy.","Dovoľte niekomu inému bez tréningu jazdiť vpred.","Pred samostatným použitím si prijmite potrebné pokyny týkajúce sa zariadenia.","Dokonca aj skúsení operátori žeriavov potrebujú znalosti o špecifických použitých ovládacích prvkoch, ochranných zariadeniach a limitoch."],"a-kennzeichnung":["Ako poznáte prípustnú nosnosť praku?","Chcete si vybrať popruh.","Vôňa materiálu.","Na príslušnom, čitateľnom označení nosnosti a údajoch výrobcu.","O dĺžke skladovania.","Prípustná nosnosť je určená označením a prevádzkovými podmienkami."],"a-sichtpruefung":["Všimnete si zreteľný rez na zdvíhacom popruhu. Ako na to idete?","Kapela má niesť náklad.","Pásku nepoužívajte a pošlite ju na testovanie alebo zamietnutie.","Prelepte rez páskou.","Používajte ho len pri obzvlášť nízkej záťaži.","Poškodené textilné popruhy môžu zlyhať a musia sa posúdiť podľa kritérií vyradenia."],"a-neigungswinkel":["Čo sa stane, ak je uhol sklonu prameňov popruhu väčší ako vertikála?","Dvojvláknový vešiak sa viac rozprestiera.","Sily prameňa vždy klesajú.","Sily vlákna zostávajú rovnaké.","Sily v prameňoch sa zvyšujú; Treba dodržať prípustné uhly a nosnosti.","So zvyšujúcim sa rozpätím sa zvyšuje ťahová sila na nosné vlákno."],"a-schwerpunkt":["Prečo potrebujete poznať ťažisko nákladu?","Zaťaženie je postavené nerovnomerne.","Aby bremeno zostalo pri zdvíhaní stabilné a nekontrolovane sa neprevrátilo.","Na výber farby popruhov.","Aby sa záťaž mohla otáčať rýchlejšie.","Nepriaznivé upevňovacie body alebo poloha ťažiska môžu viesť k prevráteniu, pošmyknutiu alebo nakloneniu."],"a-kantenschutz":["Zdvíhací popruh leží na ostrej hrane komponentu. čo treba urobiť?","Komponent by sa mal zdvihnúť.","Rýchlo zdvihnite bremeno skôr, ako sa pás poškodí.","Použite vhodnú ochranu hrán a skontrolujte typ nástavca.","Nákladnú plochu čistite iba handričkou.","Ostré hrany môžu poškodiť podporné vlákna; viazacie zariadenie musí byť zodpovedajúcim spôsobom chránené."],"a-haken":["Na čo si dávať pozor pri pripevňovaní praku?","Používate nákladný hák.","Umiestnite popruh na stranu hrotu háčika.","Bezpečnostnú klapku nechajte trvalo otvorenú.","Naložte hák podľa určenia do základne háku a dodržiavajte bezpečnostné zariadenia.","Neprípustné zaťaženie hrotu háčika a nedostatočné zaistenie môžu viesť k jeho odháknutiu."],"a-knoten":["Môžete skrátiť zdvíhací popruh, ktorý je príliš dlhý, uzlom?","Dĺžka zastávky nesedí.","nie; Používajte iba vhodný, schválený typ viazacieho prostriedku alebo vhodné viazacie zariadenie.","Áno, ak je uzol stiahnutý veľmi tesne.","Áno, pokiaľ je náklad momentálne nehybný.","Uzly môžu výrazne oslabiť textilné popruhy a nie sú povolené improvizované úpravy dĺžky."],"a-probehub":["Prečo sa bremeno spočiatku zdvíha opatrne?","Chcete sa prepravovať bezpečne.","Aby mohla čo najrýchlejšie pendlovať.","Na kontrolu polohy popruhov, stability a ťažiska.","Pretože nosnosť sa zvyšuje automaticky.","Kontrolovaný prvý zdvih pomáha odhaliť nesprávne zarážky a nestabilné polohy nákladu."],"a-lastweg":["Kde sa môžu ľudia zdržiavať počas prepravy nákladu?","Náklad sa presúva pomocou žeriavu.","Priamo pod nákladom s ochrannou prilbou.","Na bremeno, ak vydržia.","Mimo nebezpečnej oblasti a nie pod zavesenými bremenami.","Aj pri starostlivom pripevnení stále existuje nebezpečenstvo spôsobené padajúcimi alebo kývajúcimi sa nákladmi."],"a-haende":["Ako sa pri odvykaní vyhnete poraneniam pomliaždením?","Záťaž sa blíži k nosnej ploche.","Ruky a nohy držte mimo oblasti drvenia a používajte vhodné pomôcky.","Náklad držte holou rukou.","Postavte sa medzi náklad a stenu, aby ste upravili polohu.","Medzi nákladom a podperou vznikajú nebezpečné miesta zovretia."],"a-vierstraenge":["Čo platí pre rozloženie zaťaženia na štvornohom zavesení bez kompenzácie zaťaženia?","Je pripevnené pevné bremeno.","Všetky štyri pramene nevyhnutne nesú rovnaké množstvo.","Bez preukázania rovnomerného rozloženia sa nosnosť nemôže použiť ako všeobecný odhad pre štyri rovnako zaťažené pramene.","Uhol sklonu je potom irelevantný.","Nerovnomerné zaťaženie prameňa je možné pri tuhých zaťaženiach; S tým musí počítať konštrukcia a prípustná nosnosť."],"a-chemikalien":["Čo platí pri používaní textilných popruhov v kontakte s chemikáliami?","Pracujete s neznámou tekutinou.","Farba náramku spoľahlivo ukazuje jeho odolnosť.","Každý textilný pás je odolný voči všetkým chemikáliám.","Skontrolujte životnosť a informácie od výrobcu; Nepoužívajte nevhodné prostriedky.","Chemikálie môžu napadnúť závesy a nepozorovane znížiť ich nosnosť."],"a-aufbewahrung":["Ako sa popruhy skladujú po použití?","Misia sa skončila.","Čisté, suché a chránené pred poškodením podľa špecifikácií výrobcu.","Zaseknutý na zemi pod nechráneným nákladom.","Na akýkoľvek ostrý vonkajší háčik.","Vhodné skladovanie zabraňuje predčasnému opotrebovaniu a uľahčuje vizuálnu kontrolu."],"a-auswahl":["Čo treba brať do úvahy najmä pri citlivých nákladoch alebo nákladoch s ostrými hranami?","Natretý komponent stroja je potrebné presunúť.","Len rýchlosť dopravy.","Vhodné popruhy a ochranné opatrenia pre ložnú plochu a hrany.","Bez ohľadu na zaťaženie vždy rovnaké oceľové lano.","Typ nástavca a materiál musia zodpovedať geometrii, povrchu a nebezpečenstvu."],"a-abstimmung":["Operátor žeriavu na vás nemá výhľad. Ako dávate pokyny?","Ste pridelený ako útočník.","Mávate podľa ľubovôle, kým nezačne pohyb.","Stačí zavolať a odísť.","Prostredníctvom jasne dohodnutých značiek alebo inej spoľahlivej komunikácie.","Útočníci a operátori žeriavov musia jasne komunikovať; Ak to nie je jasné, pohyb sa musí zastaviť."],"b-qualifikation":["Čo človek potrebuje na bezpečnú obsluhu hydraulického rýpadla počas prevádzky?","Práce na stavbe by mal prevziať nový človek.","Príslušná kvalifikácia, pokyny týkajúce sa zariadenia a požadované priradenie.","Len vodičský preukaz na auto.","Len rýchle pozorovanie operácie.","Zamestnávateľ musí zabezpečiť potrebnú kvalifikáciu a vhodne poučiť obsluhu na danú úlohu."],"b-pruefung":["Čo je súčasťou dennej kontroly stroja?","Prevezmete bager.","Skontrolujte farbu laku a čalúnenie sedadiel.","Vizuálna kontrola a funkčné skúšky podľa návodu na obsluhu, napríklad na tesnosť a poškodenie.","Pohybujte výložníkom plnou rýchlosťou, kým sa nezastaví.","Poškodenie hydrauliky, podvozku a bezpečnostných zariadení môže viesť k vážnym nehodám."],"b-leitungen":["Čo je potrebné vedieť o podzemných potrubiach pred výkopom?","Mali by ste vykopať priekopu.","Len približná hĺbka plánovanej výkopovej jamy.","Farba nadzemného označenia je dostatočná.","Objasniť umiestnenie možných línií a určiť vhodné bezpečnostné a prieskumné opatrenia.","Elektrické, plynové alebo vodovodné potrubia môžu mať v prípade poškodenia život ohrozujúce následky."],"b-schwenkbereich":["Ako chránite ľudí v oblasti výkyvu rýpadla?","Materiál naberáte pomocou výložníka.","Odpojte alebo zabezpečte nebezpečnú oblasť a držte ľudí mimo nej.","Pred otočením pomaly pohybujte lopatou.","Prejdite cez oblasť nad hlavami.","Otočná nadstavba a náradie vytvárajú nebezpečenstvo pomliaždenia a nárazu."],"b-boeschung":["Čo je dôležité pri práci v blízkosti okraja výkopovej jamy?","Rýpadlo stojí na vybudovanej alebo naplnenej zemi.","Samotná hĺbka kopania určuje prípustné umiestnenie.","Dbajte na nosnosť a zaistenie hrany ako aj na požadované vzdialenosti podľa posúdenia rizika.","Jazdite čo najbližšie k okraju, aby ste ušetrili dosah.","Ak nie je dostatok voľného priestoru alebo stabilný podklad, násyp môže zlyhať a stroj môže spadnúť."],"b-standsicherheit":["Prečo sú svah a terén rozhodujúce pre použitie?","Stavenisko je vo svahu.","Stroj je rovnako stabilný na akomkoľvek povrchu.","Pásové podvozky eliminujú akékoľvek riziko prevrátenia.","Nerovnosti a svahy môžu ovplyvniť stabilitu; Dodržujte limity použitia.","Stabilita a bezpečnosť prevrátenia závisí od podlahy, vybavenia, nákladu a polohy stroja."],"b-wechselgeraet":["Čo kontrolujete po výmene lyžice rýpadla pomocou rýchloupínača?","Bola nainštalovaná nová príloha.","Či je správne uzamknutý a zaistený podľa návodu na obsluhu.","Stačí, či ladí farba lopaty.","Či hydraulika pracuje čo najtichšie.","Chybné zámky môžu spôsobiť pád príslušenstva."],"b-heben":["Na čo si dať pozor pri zdvíhaní voľne visiaceho nákladu bagrom?","Rýpadlo sa používa na zdvíhacie práce.","Rozhodujúca je len obvyklá kopacia sila.","Dodržiavajte prípustné zdvíhacie zaťaženie, vhodné upevňovacie body a predpísané ochranné zariadenia.","Náklad je možné zavesiť na zuby vedra.","Zdvíhanie je povolené len v rámci predpokladaných prevádzkových podmienok s vhodným vybavením."],"b-rueckwaerts":["Musíte cúvať, ale nevidíte cestu. čo je správne?","Ďalší pracovníci sú neďaleko.","Odíďte opatrne bez viditeľnosti.","Stačí zatrúbiť a pokračovať v jazde.","Zastavte, zaistite viditeľnosť a nebezpečnú oblasť alebo zorganizujte vhodné pokyny.","Cúvanie nesmie ohroziť ľudí; obmedzená viditeľnosť si vyžaduje dodatočné opatrenia."],"b-kabel":["Boom by sa mohol priblížiť k nadzemnému elektrickému vedeniu. čo to robíš?","Pracujete na tesnom stavenisku.","Vopred objasnite nebezpečnú oblasť a vhodné ochranné opatrenia so zodpovednými osobami.","Ignorujte čiaru, ak je rameno namaľované.","Výložník pohybujte len obzvlášť rýchlo.","Elektrické nebezpečenstvo vzniká pri kontakte a preskoku; sú potrebné bezpečné vzdialenosti a ochranné opatrenia."],"b-verlassen":["Ako zaparkujete bager pred odchodom?","Daj si pauzu.","Nechajte rameno voľne plávať.","Pracovný prostriedok bezpečne odložte a stroj zaistite proti pohybu a neoprávnenému použitiu.","Nechajte motor bežať a kabínu otvorenú.","Znížené pracovné vybavenie a ochrana pred neúmyselným pohybom znižujú riziko nehôd."],"b-hydraulik":["Na poškodenom potrubí si všimnete hydraulický olej pod vysokým tlakom. čo je správne?","Vyteká čiara.","Precíťte únik rukou.","Pripevnite novú svorku pod tlakom.","Bezpečne stroj odstavte, nechajte znížiť tlak a nechajte opravu vykonať autorizovaným odborným personálom.","Hydraulická kvapalina pod vysokým tlakom môže spôsobiť vážne zranenia; nikdy nekontrolujte netesnosti ručne."],"b-unterbau":["Aké je nebezpečenstvo jazdy na nestabilných povrchoch?","Zem je po daždi mäkká.","Stroj sa môže potopiť, skĺznuť alebo prevrátiť.","Disk sa automaticky rozšíri.","Vďaka tomu je otočný rozsah bezpečnejší.","Nedostatočná nosnosť môže výrazne zhoršiť stabilitu a bezpečnosť jazdy."],"b-arbeitsgeraet":["Môže niekto pracovať pod zdvihnutým náradím?","Človek chce mať pod lopatou niečo pod kontrolou.","Áno, keď motor beží na voľnobeh.","Nie, nie bez požadovanej bezpečnej opory a zaistenia pracovného zariadenia.","Áno, ak má osoba ochrannú prilbu.","Hydraulické zariadenie sa môže potopiť; Údržbárske práce si vyžadujú bezpečné pracovné vybavenie."],"b-geraeteart":["Prechádzate z hydraulického rýpadla na kolesový nakladač. Čo sa vyžaduje?","Prevádzka a pohybové správanie sú odlišné.","Len tá istá obuv.","Skúšobná jazda bez návodu.","Kvalifikácia alebo inštrukcie požadované pre nový typ stroja.","Kvalifikácia musí zodpovedať typu použitého stroja a špecifickým prevádzkovým požiadavkám."],"g-neigung":["Vediete naložený vysokozdvižný vozík na svahu. čo je dôležité?","Trasa má jasný spád.","Náklad vždy veďte dole kopcom, aj keď je ťažký.","Náklad veďte do kopca a dodržiavajte prevádzkové pokyny pre jazdu v stúpaniach.","Bez ohľadu na smer jazdy zdvihnite vidlicu na maximum.","Na stúpaniach a klesaniach musí byť náklad vždy prenášaný do kopca; Vozidlo a návod na obsluhu sa musia dodržiavať."],"g-gabelabsenken":["Prečo musí byť pri parkovaní spustená vidlica?","Vysokozdvižný vozík je odstavený na prestávku.","Aby ostatní mohli pomocou vidlice vyliezť hore.","Aby vidlica zostala viditeľnejšia z diaľky.","Aby zdvíhanie bremena nepredstavovalo zbytočné riziko zakopnutia alebo zranenia.","Znížené zariadenia na manipuláciu s nákladom znižujú riziko nehôd v dôsledku vyčnievajúcich alebo nezaistených vidlíc."],"g-fahrerwechsel":["Kolega by si chcel požičať vysokozdvižný vozík. Čo musí byť prítomné?","Kolega má od vás len ústne povolenie.","Musí mať potrebnú kvalifikáciu a operačný mandát.","Vaše vlastné zadanie sa automaticky vzťahuje aj na neho.","Pre každú firmu stačí súkromný vodičský preukaz.","Nezávislé vedenie je viazané na osobnú vhodnosť, odbornú prípravu, kvalifikáciu a operačné zaradenie."],"g-ladungssicherung":["Paleta obsahuje voľne naskladané krabice. čo je správne?","Kartónová krabica môže počas jazdy spadnúť.","Náklad pred prepravou zaistite proti skĺznutiu a pádu.","Na obzvlášť nerovnom teréne jazdite len pomaly.","Uvoľnené krabice kompenzujte vyššou polohou vidlice.","Náklad musí byť pred prepravou s pozemným dopravníkom stabilný a zabezpečený proti pádu."],"g-bodenbelastung":["Pred vami je deka s obmedzenou nosnosťou. ako sa rozhodnete?","Trasa vedie cez strednú úroveň.","Len pozor na hmotnosť vozíka bez nákladu.","Ujasnite si prípustné zaťaženie podlahy pre vysokozdvižné vozíky a bremená.","Jazdite s hybnosťou tak, aby bol strop zaťažený kratší čas.","Relevantné je celkové skutočné namáhanie plochy, vrátane vozidla, zaťaženia a dynamických vplyvov."],"g-verkehrswege":["Cestu vám skríži značený chodník. čo je správne?","Chodci majú prístup na priechod kedykoľvek.","Prednosť si môžete uplatniť vždy pomocou klaksónu.","Môžete prejsť cez značenie bez toho, aby ste boli pozorovaní.","Prispôsobte rýchlosť, dávajte pozor na chodcov a pokračujte v jazde len vtedy, keď je cesta voľná.","Dopravné cesty musia byť vedené s ohľadom na ľudí; Výstražné značky nenahrádzajú bezpečnú viditeľnosť a voľnú trasu."],"g-parkbremse":["Zaparkujete vysokozdvižný vozík na rovnom teréne. Čo to zahŕňa?","Chcete na niekoľko minút opustiť sedadlo vodiča.","Zaparkujte, zatiahnite parkovaciu brzdu a zabezpečte proti neoprávnenému použitiu.","Vozidlo nechajte iba v neutrálnej polohe.","Nechajte vidlicu vo výške hlavy, aby sa jej nikto nedotýkal.","Pred odchodom je potrebné vozík bezpečne zastaviť a zabezpečiť proti samovoľnému pohybu."],"g-typenschild":["Ktoré informácie sú záväzné pri náklade na vysokozdvižnom vozíku?","Chcete zdvihnúť ťažký stroj.","Odhadovaná nosnosť na základe veľkosti vozidla.","Údaje výrobcu v diagrame zaťaženia alebo nosnosti.","Hmotnosť poslednej prepravovanej palety.","Prípustné zaťaženie je určené údajmi výrobcu a závisí okrem iného od ťažiska bremena a výšky zdvihu."],"g-tore":["Vysokozdvižným vozíkom sa blížite k nízkemu priechodu. čo to kontroluješ?","Na vozidle je vysoký náklad.","Či je bezpečný prechod vrátane nákladu a príslušenstva.","Iba výška nosiča vidlíc bez nákladu.","Či môžete prejsť rýchlejšie, kým sa brána zatvorí.","Pred prejazdmi treba brať do úvahy svetlú výšku a šírku, ako aj rozmery nákladu a vozidla."],"g-reifen":["Pri každodennej kontrole nájdete silne poškodenú pneumatiku. čo to robíš?","Na pneumatike sú viditeľné poškodenia súvisiace s bezpečnosťou.","Jazdite pomaly až do pravidelnej údržby.","Zvýšite tlak v pneumatikách a pokračujete v jazde.","Vozidlo neuvádzate do prevádzky a nehlásite škodu.","Poškodené pneumatiky môžu zhoršiť stabilitu a ovládateľnosť; závadu treba pred použitím objasniť."],"h-absperren":["Zamestnanci prechádzajú popod vašu pracovnú plošinu. Čo je potrebné?","Hrozí nebezpečenstvo padajúceho náradia.","Vhodný ochranný alebo obmedzený priestor pod pracoviskom.","Len upozornenie, keď prvýkrát prejdete okolo.","Náradie skladujte čo najďalej od okraja koša.","Pracovný priestor pod vyvýšenými pracoviskami musí byť zabezpečený proti nebezpečenstvu padajúcimi dielmi."],"h-werkzeuge":["Ako prepravujete náradie v pracovnom koši?","Vo výške je potrebných niekoľko malých nástrojov.","Umiestnite ich voľne na zábradlie, aby boli na dosah ruky.","Uložte a zaistite tak, aby nespadli a nebránili prevádzke.","Pripevnite na vonkajšiu stranu zábradlia vo vrecku.","Voľné predmety môžu spadnúť a ohroziť ľudí; vyžaduje sa bezpečné uloženie."],"h-abstuetzung":["Na poklope šachty stojí podpera. Čo je potrebné skontrolovať?","Chcete zdvihnúť plošinu.","Len sa uistite, že je veko suché.","Či môže byť záťaž v danom bode bezpečne absorbovaná.","Či nie je potrebné použiť ostatné podpery.","Podložie a kontaktné plochy musia byť schopné bezpečne absorbovať podperné sily; Kryty je potrebné posudzovať samostatne."],"h-notaus":["Kedy by sa malo použiť zariadenie núdzového zastavenia?","Okamžite nastáva nebezpečný pohyb.","Len na konci riadnej zmeny.","Na zastavenie pri akútnom nebezpečenstve podľa návodu na obsluhu.","Ako náhrada za plánované zníženie.","Núdzové zastavenie slúži na odvrátenie nebezpečenstva, nie bežné ovládanie alebo bežné vypnutie."],"h-schraegstellung":["Varovanie pred naklonením stolíka reaguje. Ako reagujete?","Stroj je na naklonenom povrchu.","Pri nízkych pracovných výškach ignorujete varovanie.","Napriek varovaniu jazdíte do najvyššej polohy zdvihu.","Zastavíte a uvediete pódium do bezpečného stavu podľa pokynov výrobcu.","Varovania pred naklonením môžu naznačovať nedostatočnú stabilitu; ďalšie pohyby nesmú zvyšovať nebezpečenstvo."],"h-umgebung":["Čo je potrebné zorganizovať pri inštalácii v blízkosti dopravnej oblasti?","Vozidlá sa môžu dotknúť javiska.","Ochrana pred kolíziami a vhodné vedenie premávky.","Otočte pracovný kôš čo najviac nad cestu.","Len varovný hovor pred spustením.","Pracovné plošiny musia byť chránené pred kolíziami s účastníkmi cestnej premávky; inštalácia musí byť zodpovedajúcim spôsobom zabezpečená."],"h-ueberlast":["Spustí sa výstraha preťaženia v koši. čo to robíš?","Boli pozvané ďalšie nástroje.","Dokončite prácu pri vyššej rýchlosti.","Stanovte prípustné zaťaženie koša a postupujte podľa pokynov výrobcu.","Natrvalo vypnite varovný signál.","Nesmie byť prekročené maximálne povolené zaťaženie koša vrátane osôb a materiálu."],"h-quetschen":["Košík zaveziete tesne pod strechu. Ktoré nebezpečenstvo je obzvlášť dôležité?","Nad košíkom zostáva málo miesta.","Upínanie alebo drvenie medzi košom a konštrukciou.","Že motor spotrebuje viac paliva.","Že smer jazdy sa vždy automaticky obráti.","Tesné priestory nad alebo vedľa pracovného koša môžu spôsobiť vážne poranenia pomliaždením."],"h-stromausfall":["Pódium zostáva vo veľkej výške bez hlavného pohonu. čo je správne?","Normálne ovládanie koša už nereaguje.","Bez istenia zleziete po výložníku.","Čakáte do konca svojej zmeny bez toho, aby ste boli informovaní.","Začnite pripravenú záchranu pomocou vyškolených ľudí a núdzového spustenia.","Pri poruchách treba naplánovať bezpečnú záchranu; Vyškolení ľudia musia poznať núdzové funkcie."],"h-transportstellung":["Ako pripravujete podmienky na prepravu?","Pracovná plošina sa naloží na vhodné vozidlo.","Uveďte výložník a plošinu do prepravnej polohy podľa návodu na obsluhu.","Upevnite plošinu čo najďalej.","Nechajte podpery vysunuté, aby zaberali viac miesta.","Predpísaná prepravná poloha a zaistenie nákladu vychádzajú z údajov výrobcu a prepravných údajov."],"k-bremsprobe":["Čo ukazuje funkčná skúška žeriavovej brzdy pred použitím?","Chcete byť schopní bezpečne držať náklad.","Či sa brzda zastaví a udrží pohyb podľa plánu.","Len či funguje osvetlenie kabíny.","Či hák dokáže automaticky držať záťaž.","Pred použitím je potrebné skontrolovať bezpečnostné funkcie podľa špecifikácií."],"k-schraegzug":["Môžete ťahať bočné bremeno pod uhlom so žeriavom?","Hák nie je vertikálne nad nákladom.","Áno, ak má žeriav ešte rezervu zaťaženia.","Nie, bremená sa nesmú ťahať neprípustnými diagonálnymi ťahmi.","Áno, ak sú popruhy obzvlášť krátke.","Diagonálne ťahanie môže spôsobiť nekontrolované pohyby a dodatočné namáhanie žeriavu a popruhov."],"k-verhakt":["Na spodnej konštrukcii visí náklad. čo je správne?","Pri zdvíhaní je cítiť odpor.","Stále dvíhaš, kým to nezmizne.","Náklad posúvate do strán trhavo.","Zastavíte a necháte nástavec alebo blokovanie bezpečne odstrániť.","Zaseknuté bremená sa nesmú silou roztrhnúť, pretože môžu vzniknúť neprijateľné sily."],"k-anzuheben":["Čo kontrolujete pri prvom krátkom zdvihnutí zaveseného bremena?","Náklad sa zdvihne niekoľko centimetrov od zeme.","Či visí v rovnováhe a doraz je bezpečný.","Či sa človek môže dať priamo pod náklad.","Či sa žeriav stáva stabilnejším rýchlym otáčaním.","Krátke riadené zdvíhanie sa používa na kontrolu pripevnenia, vyváženia a bezpečného správania nákladu."],"k-lastweg":["Kde by mala byť trasa prepravy nákladu žeriava?","Pod možnou dráhou zaťaženia je viacero pracovísk.","Ak je to možné, nad obsadenými pracovnými stanicami.","Na plánovanej, jasnej ceste bez ohrozenia ľudí.","Vždy diagonálne cez najrušnejšiu oblasť.","Nákladové trasy musia byť usporiadané tak, aby zavesené bremená neohrozovali ľudí."],"k-signalverlust":["Rádiové spojenie s maršálom sa prerušilo. čo to robíš?","Nevidíte samotnú dráhu načítania.","Pomaly pokračujete v pohybe.","Experimentálne šviháte predchádzajúcim smerom.","Pohyb zastavíte, kým nedôjde k jasnému a bezpečnému porozumeniu.","Ak chýba komunikácia, mätúci pohyb nákladu nemusí pokračovať."],"k-haken":["Bezpečnostný hák sa spoľahlivo nezatvára. čo je správne?","Pri kontrole sa zistí chybný uzáver.","Chybu je potrebné pred ďalším použitím odborne opraviť.","Sponu pevne zviažete sťahovacou páskou.","Hák používate len na ľahké bremená.","Chybné zaisťovacie zariadenia na hákoch môžu viesť k uvoľneniu popruhov a musia sa odstrániť."],"k-zugrichtung":["Čo je dôležité pre vertikálnu podporu bremena?","Náklad sa má zdvihnúť zo stroja.","Hák žeriava by mal byť zarovnaný nad ťažiskom bremena.","Háčik by mal byť umiestnený čo najviac nabok.","Pred zdvíhaním je potrebné náklad zatlačiť.","Silový efekt, ktorý je čo najvertikálnejší nad ťažiskom bremena, zabraňuje neprípustným bočným silám a nekontrolovanému vychýleniu."],"k-wartung":["Na žeriave je zaznamenaný nezvyčajný zvuk brúsenia. Ako na to idete?","Hluk vzniká pri zdvíhaní.","Zakryte hluk vyššou rýchlosťou.","Bezpečne zastavte operácie, nahláste chyby a nechajte ich vyriešiť.","Pokračujte v práci bez upozornenia až do prestávky.","Viditeľné zmeny môžu naznačovať poškodenie súvisiace s bezpečnosťou a vyžadujú si kontrolu."],"k-absetzen":["Čo musí byť zaručené pri spúšťaní bremena žeriava?","Na povrchu je umiestnené ťažké bremeno.","Náklad môže ležať nezaistený na naklonenom povrchu.","Závesy sa odstránia, kým ešte pláva.","Náklad je stabilný a zabezpečený proti prevráteniu alebo odvaleniu.","Bremeno sa smie uvoľniť zo závesného zariadenia až po jeho bezpečnom odložení a zaistení stability."],"l-schwerpunkt":["Prečo musí byť pred úderom známe ťažisko?","Prepravovať sa má asymetricky tvarovaný stroj.","Aby bremeno zostalo pri zdvíhaní čo najrovnomernejšie.","Aby bolo možné popruhy vybrať tak dlho, ako si želáte.","Aby prípustná nosnosť nehrala rolu.","Poloha ťažiska ovplyvňuje rozloženie zaťaženia a bezpečnú rovnováhu pri zdvíhaní."],"l-etikett":["Zdvíhací popruh nemá čitateľný štítok s nosnosťou. čo je správne?","Značenie sa zmenilo na nepoznanie.","Odhadnite nosnosť podľa farby.","Zdvíhací popruh nepoužívajte, kým nebude jasne preukázaná jeho vhodnosť.","Pri malých nákladoch použite pás iba raz.","Pre závesy sú potrebné vhodné označenia; Nevysvetliteľná nosnosť vylučuje bezpečný výber."],"l-kantenschutz":["Textilný pás leží na ostrom oceľovom okraji. Čo je potrebné?","Náklad má ostré hrany.","Utiahnite pás čo najtesnejšie bez ochrany.","Vykonajte ťah rýchlejšie.","Použite vhodnú ochranu hrán alebo iné vhodné závesné zariadenie.","Ostré hrany môžu poškodiť alebo prerezať textilné popruhy; je potrebná primeraná ochrana."],"l-spreizwinkel":["Ako ovplyvňuje väčší uhol sklonu zaťaženie závesov?","Náklad sa zdvíha pomocou dvoch šikmých lán.","Pri menej priaznivých uhloch sa sily v prameňoch môžu zvýšiť.","Sily prameňov miznú.","Uhol nemá žiadny vplyv na napätie.","Pri menej priaznivom dorazovom uhle sa môžu zvýšiť sily na prameň; Musia sa dodržiavať tabuľky nosnosti."],"l-knoten":["Dá sa závesné lano skrátiť podľa želania pomocou uzla?","Lano je príliš dlhé na plánované zaťaženie.","Áno, pevný uzol zlepšuje nosnosť.","Nie, používajte iba schválené metódy skracovania a kotvenia.","Áno, ak je uzol zaistený páskou.","Neprípustné uzly oslabujú závesy a menia ich prípustnú nosnosť."],"l-zeichen":["Čo platí pre komunikáciu s osobou obsluhujúcou žeriav?","Dráha nákladu je čiastočne zakrytá.","Niekoľko ľudí dáva súčasne rôzne signály.","Používajú sa jasné, vopred dohodnuté signály.","S rádiovými žeriavmi nie je nikdy potrebná komunikácia.","Jasné značky a jasné zodpovednosti zabraňujú nebezpečným nesprávnym pohybom."],"l-sichtpruefung":["Kedy by sa mali popruhy kontrolovať na viditeľné chyby?","Chcete použiť závesnú reťaz.","Pred použitím dávajte pozor na vonkajšie viditeľné poškodenia.","Iba ak sa už stala nehoda.","Pri prvom nákupe iba raz.","Pred každým použitím sa musí posúdiť bezpečný pracovný stav; Viditeľné poškodenie znemožňuje bezpečné používanie."],"l-drehung":["Zdvihnutý náklad sa začne nekontrolovateľne otáčať. čo to robíš?","Náklad sa pohybuje v dráhe zaťaženia.","Vložíte ruku medzi náklad a stenu.","Položíte sa pod bremeno a budete sa ho držať.","Udržujete si odstup a kontrolovane necháte pohyb zastaviť.","Nekontrolované pohyby nákladu vytvárajú nebezpečenstvo pomliaždenia a nárazu; Ľudia musia opustiť nebezpečnú oblasť."],"l-ablegen":["Kedy môžu byť popruhy odstránené z nákladu?","Náklad je umiestnený na podperách.","Ak je náklad stabilný a zabezpečený proti prevráteniu alebo odvaleniu.","Hneď ako sa prvýkrát dotkne zeme, bez ohľadu na jeho polohu.","Kým sa stále vznášate, aby ste ušetrili čas.","Závesy môžu byť odstránené až po ich bezpečnom a stabilnom odložení."],"l-ketten":["Reťazový popruh má silne ohnutý článok. čo to robíš?","Poškodenie je viditeľné ešte pred zdvihnutím.","Omotajte poškodené miesto drôtom.","Vyraďte reťaz z používania a nechajte ju odborne skontrolovať.","Náklad zdvihnite len o polovicu vyššie.","Deformované články reťaze sú viditeľné poškodenia, ktoré môžu brániť bezpečnému použitiu."],"b-einweiser":["Čo je dôležité, keď je viditeľnosť z rýpadla obmedzená?","Časť budovy zakrýva oblasť jazdy.","Vhodné vizuálne opatrenia alebo pokyny a jasná komunikácia.","Len pozor na kapotu.","Jazdite cez otočnú oblasť napriek tomu, že ste neviditeľní.","Ak je viditeľnosť obmedzená, nebezpečenstvám sa musí zabrániť dodatočnými organizačnými a technickými opatreniami."],"b-aushub":["Kde je možné ukladať výkopový materiál v blízkosti stavebnej jamy?","Okraj jamy nesmie byť vystavený ďalšiemu riziku.","Naskladajte priamo na okraj, aby príjazdové cesty zostali voľné.","Skladujte v dostatočne bezpečnej vzdialenosti a podľa špecifikácií staveniska.","Umiestnite na voľné podpery bez ďalšieho skúšania.","Vyťažený materiál môže dodatočným zaťažením ohroziť násypy a paženie; Je potrebné dodržiavať bezpečnostné vzdialenosti."],"b-personen":["Môžu ľudia zostať v oblasti hojdania počas pohybu rýpadla?","Človek chce pri ryžovaní merať.","Áno, pokiaľ nosí ochrannú prilbu.","Áno, ak sa bager pomaly kýve.","Nie, nebezpečná oblasť musí byť pred pohybom voľná.","V oblasti otáčania existuje riziko vážneho pomliaždenia a poranenia nárazom; oblasť musí byť udržiavaná voľná."],"b-ladung":["Ako bezpečne prepravujete materiál pomocou kolesového nakladača?","Cez dvor by sa mala preháňať naplnená lopata.","S vhodnou nízkou transportnou polohou a voľnou cestou.","So zdvihnutou lopatkou pre lepšiu viditeľnosť.","S otvorenými dverami a silným uhlom riadenia.","Vhodná prepravná poloha znižuje riziko prevrátenia a zlepšuje jazdnú stabilitu."],"b-anbaupruefung":["Čo kontrolujete po pripojení príslušenstva?","Bola pripevnená nová lopata.","Len čistota laku.","Bezpečné uzamknutie a funkcia podľa návodu na obsluhu.","Stačí, či zariadenie zvonku vyzerá rovnako.","Nesprávne zámky na rýchlospojkách môžu viesť k neúmyselnému uvoľneniu príslušenstva."],"b-einstieg":["Ako sa bezpečne dostanete do kabíny rýpadla?","Schody sú po daždi špinavé.","Vylezte do kabíny cez výložník.","Dostaňte sa na húsenice jedným skokom.","Používajte určené schodíky a držadlá a očistite špinavé schodíky.","Vhodné stúpania a bezpečné záchytné body znižujú riziko pošmyknutia a pádu."],"b-graben":["Stena priekopy vykazuje trhliny a rozpadá sa. čo je správne?","Pracujete hneď vedľa priekopy.","Zastavte práce a nechajte zodpovedných zabezpečiť výkopovú jamu.","Jednoducho prejdite bližšie k okraju, aby ste zatvorili priekopu.","Prehĺbte priekopu ďalej bez ochrany.","Trhliny a pohyby zeme môžu naznačovať nestabilitu a vyžadujú si ďalšie posúdenie bezpečnosti."],"b-betanken":["Na čo si dávať pozor pri tankovaní zemného stroja?","Nádrž je takmer prázdna.","Zaistite motor a zápalné zdroje podľa pokynov výrobcu a zabráňte rozliatiu.","Benzín alebo naftu vždy dopĺňajte v kabíne.","Pri tankovaní fajčite, keď je bezvetrie.","Nebezpečenstvo požiaru a životného prostredia pri manipulácii s palivom si vyžaduje primerané ochranné opatrenia."],"b-laufwerk":["Prečo je potrebné pravidelne kontrolovať pásy a podvozok?","Počas jazdy si všimnete nezvyčajné vibrácie.","Aby sa stroj mohol pohybovať rýchlejšie.","Pretože poškodenie môže ovplyvniť bezpečné vedenie a stabilitu.","Pretože práca je vždy povolená bez vizuálnej kontroly.","Poškodenie pohonu môže ovplyvniť manévrovateľnosť, stabilitu a bezpečnú prevádzku."],"b-einweisen":["Čo je potrebné pri práci v blízkosti verejnej pešej premávky?","Bager pracuje priamo na okraji chodníka.","Chodci by sa mali pohybovať cez hojdaciu plochu sami.","Stačí nalepiť ceduľku na lopatu.","Efektívne uzatvorte nebezpečnú oblasť a bezpečne usmernite premávku.","Tretie osoby nesmú vstúpiť do nebezpečnej zóny strojov na zemné práce; Nevyhnutné sú vhodné bariéry a dopravné vedenie."],"g2-fahrweg":["Na ceste pred vami je rozliata tekutina. Ako na to idete?","Vysokozdvižný vozík by jazdil priamo po klzkej ploche.","Zastavte jazdu a zabezpečte alebo odstráňte nebezpečné miesto.","So zdvihnutou vidlicou prejdite cez miesto čo najrýchlejšie.","Dúfam v suchšie pneumatiky a pokračovať v jazde bez zmeny.","Znečistené cesty ohrozujú stabilitu a pred jazdou po nich musia byť primerane zabezpečené."],"g2-sichtladung":["Vysoká paleta blokuje výhľad dopredu. čo je správne?","Musíte ísť autom do skladu a nevidíte trasu.","Zdvihnite paletu, kým neuvidíte pod ňu.","Jazdite iba pomocou vhodných a bezpečných metód, ako je cúvanie s voľným výhľadom.","Stále môžete jazdiť po ceste bez smerovky a voľného výhľadu.","Smer jazdy a viditeľnosť musia umožňovať bezpečné sledovanie dopravnej cesty; Náklad nesmie nahradiť vizuálnu kontrolu."],"g2-fussgaengerstop":["Chodec sa zastaví hneď vedľa vysokozdvižného vozíka. čo to robíš?","Osoba sa nachádza v možnom rozsahu jazdy a otáčania.","Predbehnite chodca krátkym zrýchlením.","Prejdite okolo osoby so zdvihnutým nákladom.","Zastavte a pokračujte v jazde len v bezpečnej vzdialenosti.","Ľudia sa musia zdržiavať mimo nebezpečnú oblasť; V prípade potreby treba cestu prerušiť."],"g2-hubmast":["Na zdvíhacom stožiari si všimnete poškodené hydraulické vedenie. Čo platí?","Z náradia viditeľne uniká hydraulický olej.","Vyraďte vysokozdvižný vozík z prevádzky a nahláste poškodenie.","Pri zdvíhaní rukou skontrolujte netesnosť.","Menšie bremená zdvíhajte len do konca smeny.","Hydraulické poškodenie môže viesť k nekontrolovaným pohybom; bezpečné používanie nie je až do testu zaručené."],"g2-lagerregal":["Chcete uložiť paletu na policu. Čo skontrolujete ako prvé?","Úroveň police je vysoká a nosnosť musí byť zachovaná.","Zatlačte paletu na policu čo najrýchlejšie.","Skontrolujte vhodnosť odkladacieho priestoru, hmotnosti nákladu a voľného úložného priestoru.","Odhadnite celkovú hmotnosť výlučne na základe počtu škatúľ.","Regály a zariadenia na uchopenie nákladu musia zodpovedať situácii nákladu a skladovania."],"g2-batterieschaden":["Batéria vysokozdvižného vozíka je zvonka poškodená. čo je správne?","Pred zaťažením sú zaznamenané praskliny alebo nezvyčajná tekutina.","Poškodenie prelepte lepiacou páskou a ihneď zaťažte.","Nechajte batériu nabíjať inú osobu bez toho, aby ju kontrolovala.","Nenabíjajte ani nepoužívajte a informujte zodpovedných odborníkov.","Poškodené batérie predstavujú elektrické a chemické nebezpečenstvo a vyžadujú si odborné posúdenie."],"g2-fahrerkabine":["Čo platí pre voľne uložené predmety v priestore vodiča?","Náradie je na podlahe vedľa ovládacích pedálov.","Odstráňte predmety a udržiavajte pracovnú oblasť voľnú.","Počas jazdy držte náradie iba jednou nohou.","Uvoľnené časti schovajte pod sedadlom vodiča.","Uvoľnené predmety môžu zablokovať pedále a zhoršiť bezpečnú prevádzku vozidla."],"g2-uebergabe":["Vysokozdvižný vozík preberáte po zmene zmeny. Čo to zahŕňa?","Vozidlo naposledy použil kolega.","Predpokladajme, že kolega prevzal všetky kontroly.","Vykonajte potrebnú kontrolu a informujte sa o známych závadách.","Začnite cestu bez toho, aby ste sa pozerali na stroj.","Preberajúca osoba sa musí pred použitím uistiť, že je v bezpečnom stave."],"g2-transportsicherung":["Na palete je uvoľnený vysoký predmet. ako sa správaš?","Náklad by sa mohol pri brzdení prevrátiť dopredu.","Vidlicu noste obzvlášť vysoko, aby náklad zostal stabilný.","Len pomaly prechádzajte zákrutami, choďte rovno rýchlejšie.","Náklad postavte stabilne a zaistite ho proti prevráteniu alebo pádu.","Voľné bremená musia byť pred prepravou stabilizované, aby brzdenie a jazdné pohyby nespôsobili ich pád."],"g2-arbeitsende":["Čo je dôležité pri vysokozdvižnom vozíku bez dozoru?","Ukončíte smenu a opustíte oblasť.","Vozidlo bezpečne odstavte a zaistite proti samovoľnému pohybu a neoprávnenému použitiu.","Nechajte kľúč dnu, aby kolegovia našli stroj.","Nechajte vidličku vo výške očí, aby bola viditeľná.","Bezpečné parkovanie zahŕňa manipuláciu so zníženým nákladom a ochranu proti pohybu a neoprávnenému uvedeniu do prevádzky."],"g2-bremsweg":["Prečo si musíte dávať pozor najmä na brzdnú dráhu pri zaťažení?","Vysokozdvižný vozík prepravuje ťažký tovar cez skladovú uličku.","Vždy brzdite neskôr s ťažkým nákladom ako bez nákladu.","Rýchlosť prispôsobte viditeľnosti, terénu a zaťaženiu.","Pri brzdení prudko zdvihnite náklad, aby ste lepšie spomalili.","Hmotnosť a stav vozovky ovplyvňujú brzdnú dráhu; kľúčová je prispôsobená rýchlosť."],"g2-rampe":["Čo kontrolujete pred stúpaním na strmú rampu?","Trasa môže byť pre vozidlo príliš strmá.","Jazdite po rampe maximálnou rýchlosťou bez ohľadu na sklon.","So zdvihnutým nákladom prejdite cez okraj rampy.","Skontrolujte prípustný sklon a bezpečný prevádzkový režim zo špecifikácií vozidla.","Môžu sa použiť iba rampy v rámci zamýšľaných prevádzkových limitov; Rozhodujúci je návod na obsluhu a riadenie záťaže."],"g2-zinke":["Paleta je širšia ako vzdialenosť vidlíc. Čo je potrebné vziať do úvahy?","Plánujete vziať na seba nezvyčajne veľký náklad.","Nastavte vzdialenosť vidlíc a upevňovacie body podľa zaťaženia.","Ak je náklad príliš široký, použite iba jeden hrot.","Zdvihnite náklad pod uhlom, kým nedosiahne správnu polohu.","Rovnomerné a primerané tlmenie zaťaženia znižuje pošmyknutie a prevrátenie."],"g2-betriebsanweisung":["Akú úlohu zohráva prevádzková regulácia dopravy?","V sklade platia vyznačené jednosmerné a pešie plochy.","Pri vysokozdvižných vozíkoch platia len pravidlá verejnej cestnej premávky.","Dodržujte určené trasy a pravidlá premávky.","Po naložení vozidla ignorujte označenia.","Firemné trasy a bezpečnostné pravidlá chránia premávku vysokozdvižných vozíkov a peších ľudí."],"g2-nothalt":["Riadenie počas jazdy reaguje nezvyčajne. čo je správne?","Vozidlo už nie je možné ovládať ako obvykle.","Jazdite pri vyšších rýchlostiach, aby bolo riadenie citlivejšie.","Chybu kompenzujte obzvlášť veľkými výchylkami riadenia.","Zastavte na bezpečnom mieste a nechajte vozidlo skontrolovať.","Zhoršené riadenie ohrozuje bezpečné vedenie; stroj sa nesmie ďalej nekontrolovane prevádzkovať."],"g2-anschlagkette":["Chcete premiestniť voľne visiaci náklad pomocou vysokozdvižného vozíka. Čo platí?","Náklad by mal visieť na háku pod vidlicami.","Len so schváleným zariadením a vhodným nosným zariadením.","Akákoľvek reťaz bude stačiť, ak náklad nie je ťažký.","Upevnite reťaz priamo medzi obe vidlice.","Voľne visiace bremená menia stabilitu; Vyžaduje sa schválenie výrobcu a vhodné vybavenie."],"g2-rollenlast":["Valcový komponent leží nezaistený na palete. čo to robíš?","Náklad sa môže počas prepravy prevrátiť.","K palete pristupujte obzvlášť trhavo.","Pred nabratím palety zaistite komponent proti rolovaniu.","Umiestnite hroty dostatočne vysoko, aby komponent nebol viditeľný.","Kruhové alebo valivé bremená vyžadujú spoľahlivú ochranu proti zmenám polohy."],"g2-pruefplakette":["Ako viete, či je možné použiť vysokozdvižný vozík?","Na stroji je nalepená kontrolná nálepka.","Akákoľvek nálepka vždy nahrádza každodennú vizuálnu kontrolu.","Nedostatok vôle sa dá nahradiť opatrnou jazdou.","Okrem kontroly vozidla treba brať do úvahy aj platný stav testu a prevádzkové schválenie.","Opakované testovanie a každodenné prevádzkové kontroly plnia rôzne bezpečnostné funkcie."],"g2-licht":["Osvetlenie v sklade zrazu zhaslo. čo je správne?","Už nemôžete bezpečne vidieť prekážky na ceste.","Zastavte jazdu, kým nebude zaručená bezpečná viditeľnosť.","Zvýšte rýchlosť jazdy, aby ste opustili tmavú oblasť.","Pokračujte v jazde so zdvihnutými vidlicami bez vizuálnej kontroly.","Po trase, ktorú nemožno bezpečne prehliadnuť, sa nesmie jazdiť bez účinných bezpečnostných opatrení."],"g2-ueberhang":["Náklad ďaleko presahuje bočnú stranu vidlice. čo to kontroluješ?","Paletu chcete prepraviť cez úzku bránu.","Kompenzujte bočnú projekciu rýchlym zakrivením.","Pred jazdou posúďte voľný priestor, stabilitu a prípustnú nosnosť.","Poháňajte náklad maximálnou rýchlosťou bez ohľadu na jeho tvar.","Previsy zvyšujú riziko kolízie a môžu zmeniť stabilitu a požadovaný dopravný priestor."],"g2-wartungsbereich":["Pred priestorom údržby sú zábrany. ako sa správaš?","Vaša zvyčajná trasa je dočasne uzavretá.","Krátko presuňte zábrany a prejdite nepozorovane.","Jazdite priamo cez pracovnú oblasť pod zaťažením.","Dodržujte uzávierku a vyberte si schválenú alternatívnu trasu.","Do uzavretých priestorov sa nesmie vchádzať ani cez nich prechádzať bez povolenia."],"g2-bremsprobe":["Kedy má zmysel funkčná skúška prevádzkovej brzdy?","Vysokozdvižný vozík si pripravíte pred prácou.","V rámci požadovanej kontroly pred použitím.","Vykonávajte iba po vážnej nehode.","Iba ak už vozík dosiahol vysokú rýchlosť.","Pred použitím sa skontroluje funkčnosť zariadení dôležitých pre bezpečnosť."],"g2-fahrzeuganhaenger":["Chcete ťahať príves s vysokozdvižným vozíkom. Čo sa vyžaduje?","Spoločnosť plánuje prepravu s pripojeným nákladom.","Každý príves priviažte k vidlici bez kontroly.","Dodržujte schválenie výrobcu, vhodnú spojku a prípustné zaťaženie v ťahu.","Stačí zvýšiť tlak v pneumatikách a vyraziť.","Prevádzka vlaku je možná len bezpečne v rámci technických špecifikácií a s vhodným spojením."],"g2-rueckfahrt":["Čo je dôležité pri cúvaní s vysokozdvižným vozíkom?","V skladovej uličke je neprehľadná oblasť.","Vždy sa pozerajte len do spätného zrkadla bez ohľadu na okolie.","Jazdite bez viditeľnosti, pokiaľ ste raz stlačili klaksón.","Bezpečne sledujte trasu a priestor ľudí a v prípade potreby ich nechajte poučiť.","Cúvanie si vyžaduje voľný výhľad alebo účinné dodatočné bezpečnostné opatrenia."],"g2-lastentnahme":["Vyberiete paletu z vysokej police. čo je správne?","Paleta nemusí byť vycentrovaná.","Pred spustením náklad bezpečne zdvihnite a stabilizujte.","Pri vyťahovaní nechajte paletu kývať do strany.","Skontrolujte spodnú časť zdvihnutej palety, či nie je poškodená.","Riadené zdvíhanie a spúšťanie zabraňuje pádu bremien a nebezpečným pohybom."],"h2-absenkweg":["Prečo musí zostať priestor pod pracovnou plošinou voľný?","Kôš sa spustí a materiály sa umiestnia pod neho.","Materiály zatlačte pomocou koša.","Dávajte pozor len na oblasť nôh operátora.","Zabráňte riziku pomliaždenia a kolízie pri spúšťaní.","Oblasť spúšťania nesmie obsahovať žiadne osoby alebo prekážky, ktoré by sa mohli zachytiť."],"h2-transporthoehe":["Ako presuniete mobilné pódium cez nízky priechod?","Svetlá výška je nižšia ako pri predĺženom ramene.","Umiestnite plošinu do vhodnej prepravnej polohy podľa návodu na obsluhu.","Nechajte rameno vysunuté a pohybujte sa pod stropom.","Pritlačte kôš na stranu rámu dverí.","Pri jazdných pohyboch musí celková výška a prepravná poloha zodpovedať údajom výrobcu a priechodu."],"h2-bodenoeffnung":["V podlahe vedľa javiska je nezabezpečený otvor. Ako reagujete?","Hnací alebo podporný bod sa nachádza v blízkosti otvoru.","Umiestnite podperu priamo na okraj otvoru.","Zmeňte miesto inštalácie alebo si nechajte odborne skontrolovať nosnosť a zaistenie.","Nebezpečné miesto zakryte iba kartónovou krabicou.","Otvory a okrajové oblasti môžu pri zaťažení podpery zlyhať a musia sa efektívne zohľadniť."],"h2-rettungsperson":["Prečo musí byť druhá osoba oboznámená s postupom záchrany?","Operátor sa môže stať nespôsobilým v hornej časti.","Takže práca v koši môže vo všeobecnosti prebiehať bez zabezpečenia.","Aby bolo možné javisko ovládať rýchlejšie, ako je povolené.","Aby bolo možné v prípade núdze spustiť bezpečnú záchranu.","Záchranná koncepcia musí brať do úvahy pozemnú pomoc v prípade poruchy alebo núdze."],"h2-werkzeugabwurf":["Čo platí pre nástroje vo vysokej nadmorskej výške?","Uvoľnený nástroj by mohol prepadnúť cez okraj koša.","Zaistite náradie tak, aby nikoho neohrozilo alebo nespadlo.","Jednoducho umiestnite nástroje na zábradlie, aby ste znížili zaťaženie.","V prípade potreby zhoďte náradie z koša.","Padajúce predmety ohrozujú ľudí pod nimi; Materiál musí byť bezpečne skladovaný."],"h2-trittstufe":["Ako ďalšie miesto na státie v koši by mala slúžiť krabica. čo je správne?","Inak sa na pracovisko sotva dostanete.","Položte krabicu na zábradlie a vylezte na ňu.","Nelezte na improvizované vyvýšeniny; Používajte vhodné pracovné prostriedky.","Zámerne zaťažte kôš nad povolenú výšku.","Improvizované vyvýšenia zhoršujú predpokladanú ochranu proti pádu a nie sú povolené."],"h2-lastverteilen":["Na čo si dávať pozor, keď je v pracovnom koši viacero ľudí?","Dvaja ľudia pracujú v koši s ťažkými nástrojmi.","Záťaž posúďte výlučne na základe veľkosti nástroja.","Ťažké náradie skladujte priamo na ochrannom zábradlí.","Neprekračujte povolené zaťaženie koša vrátane osôb a náradia.","Povolená nosnosť zahŕňa všetky osoby, materiál a náradie v koši."],"h2-abstuetzplatte":["Kedy sa zvažujú dodatočné podložky pre podpery?","Inštalačná podlaha znesie len obmedzené zaťaženie.","Ak je to potrebné pre bezpečné rozloženie zaťaženia podľa špecifikácií.","Aby boli podpery umiestnené čo najbližšie k okraju stavebnej jamy.","Ak chcete použiť dlhší rozsah bez informácií od výrobcu.","Pre bezpečné podporné sily sú potrebné dostatočné kontaktné plochy."],"h2-baugrube":["Pódium by malo byť umiestnené priamo na okraji stavebnej jamy. čo to kontroluješ?","Podložie mohlo bočne ustúpiť kvôli výkopovej jame.","Predĺžte podpery do výkopovej jamy.","Zabezpečte dostatočnú bezpečnú vzdialenosť a nosnosť podkladu.","Riziko kompenzujte len pomalým zdvíhaním koša.","Výkopové jamy môžu ovplyvniť stabilitu v dôsledku porušenia svahu a podložia."],"h2-witterung":["Počas používania sa námraza usadzuje. ako sa správaš?","Ovládacie plochy a pracovná plocha sa vyhladia.","Zdvihnite pódium, aby ste sa vyhli snehu a ľadu.","Ignorujte varovania, pokiaľ je plošina rozsvietená.","Prerušte prácu a prehodnoťte prevádzkové podmienky podľa návodu na obsluhu.","Zmeny počasia môžu zmeniť zodpovednosť, prevádzkyschopnosť a bezpečné limity používania."],"h2-aufbaukontakt":["Oceľová konštrukcia obmedzuje dráhu koša. čo je dôležité?","Pri zdvíhaní hrozí nebezpečenstvo pomliaždenia medzi košíkom a nosičom.","Naplánujte si pohyby tak, aby vaše telo a košík neboli uväznené.","Zrýchlite cestu, aby kôš prešiel okolo rýchlejšie.","Konštrukciu s košíkom zatlačte nabok.","Zvieracie body medzi plošinou a prostredím vyžadujú starostlivé sledovanie a kontrolovaný pohyb."],"h2-sicherheitsabstand":["Kedy musí byť nebezpečná oblasť javiska ohraničená?","Popod lokalitu prechádza trasa MHD.","Iba ak už nejaký predmet spadol.","Ak by mohli byť pohybom alebo padajúcimi predmetmi ohrozené tretie osoby.","Nikdy, keďže pracovný kôš v podstate predchádza všetkým nebezpečenstvám.","Priestor pod a vedľa javiska musí byť chránený pred predvídateľným nebezpečenstvom."],"h2-korbtor":["Čo platí pre vstupné dvere pracovného koša?","Už ste v pracovnej výške.","Nechajte dvere otvorené, aby ste sa mohli rýchlejšie dostať von.","Zviažte dvere natrvalo otvorené lanom.","Nechajte dvierka zatvorené podľa dodaného uzamykacieho mechanizmu.","Poskytnuté zámky sú súčasťou ochranných opatrení proti pádu z pracovného koša."],"h2-energieleitung":["Čo platí, ak nie je nadzemné vedenie bezpečne vypnuté?","V ich blízkosti pracujete s pracovnou plošinou.","Zabezpečte určené bezpečnostné vzdialenosti a potrebné ochranné opatrenia.","Presuňte kôš tesne pred čiaru, pokiaľ sa ho nedotknete.","Dôverujte plastovým pneumatikám a pracujte bez medzier.","Elektrické preskoky sú možné aj bez priameho kontaktu; Požadujú sa bezpečnostné vzdialenosti."],"h2-schwanken":["Pracovný kôš sa začne neobvykle silno kývať. čo je správne?","Pohyb už nie je kontrolovaný.","Prestavujte sa nekontrolovateľne rýchlymi protipohybmi.","Zastavte pohyb a skontrolujte príčinu alebo prevádzkové podmienky.","Pridajte do košíka ďalších ľudí, aby bol ťažší.","Nezvyčajné vibrácie môžu naznačovať nevhodné prevádzkové podmienky alebo poruchu."],"h2-ladegeraet":["Nabíjací kábel pre elektricky ovládaný stolík je poškodený. čo to robíš?","Pri spájaní je viditeľná poškodená izolácia.","Dotknite sa poškodenia mokrými rukavicami.","Zatlačte zástrčku do zásuvky čo najsilnejšie.","Nezačínajte proces nabíjania a nechajte kábel odborne skontrolovať.","Poškodené elektrické vedenie predstavuje riziko úrazu elektrickým prúdom a požiaru."],"h2-gelaenderanbau":["Dokážete sami odstrániť zábradlie, aby ste sa dostali bližšie?","Komponent bráni ľuďom priblížiť sa k pracovisku.","Ochranné zariadenia svojpomocne neupravujte ani neodstraňujte.","Po zdvihnutí odskrutkujte zábradlie a nainštalujte ho neskôr.","Pokračujte v práci bez zábradlia, pokiaľ pri ňom niekto stojí.","Konštrukčné ochranné zariadenia sa nesmú meniť bez povolených špecifikácií a opatrení bezpečnej výmeny."],"h2-lastkran":["Dá sa plošina použiť ako žeriav na zdvíhanie bremena?","Materiál by sa mal prepravovať voľne visiaci vedľa pracovného koša.","Vždy, keď je hmotnosť nižšia ako hmotnosť vášho vlastného tela.","Iba ak výrobca a zariadenie výslovne povoľujú toto špeciálne použitie.","Jednoducho pripevnite hák na zábradlie a zdvihnite materiál.","Zdvíhacie pracovné plošiny nie sú automaticky určené na prácu so žeriavom alebo na dodatočné zavesenie bremien."],"h2-arbeitsvorbereitung":["Čo zahŕňa príprava na nové miesto?","Ešte nepoznáte stavenisko.","Stačí odhadnúť vzdialenosť k najbližšiemu parkovisku.","Bez ohľadu na okolie ho okamžite úplne predĺžte.","Posúdiť nebezpečenstvá, pôdu, dopravné cesty, záchranu a vhodnosť vybavenia.","Posúdenie rizika súvisiaceho s miestom je predpokladom bezpečných prevádzkových podmienok."],"h2-kabelschlaufe":["Cez dráhu javiska leží napájací kábel. čo je správne?","Kábel by sa mohol počas pohybu zachytiť.","Uvoľnite cestu a chráňte elektrické káble pred poškodením.","Použite kábel s kolesami ako cestný prah.","Zdvihnite kôš bez toho, aby ste skontrolovali plochu podlahy.","Prebehnuté alebo stlačené káble môžu spôsobiť elektrické a mechanické nebezpečenstvo."],"h2-leitungsnaehe":["Kto objasňuje ochranné opatrenia na elektrickom systéme?","Platforma by mala fungovať v blízkosti zariadení pod napätím.","Osoba v košíku sa rozhoduje výlučne podľa oka.","Zapojte zodpovedné orgány a implementujte koordinované ochranné opatrenia.","Vzdialenosť sa určí až po začatí prác.","Práca v blízkosti elektrických systémov si vyžaduje plánované a koordinované ochranné opatrenia."],"h2-funkkommunikation":["Prečo musia byť signály medzi podlahou a košom čisté?","Osoba na zemi pomáha pri manévrovaní.","Aby viacero ľudí mohlo dávať súčasne protichodné pokyny.","Aby bolo možné núdzové spustenie vyskúšať bez pokynov.","Takže pohyby sa vykonávajú až po jasnej komunikácii.","Jasná komunikácia znižuje nesprávne pohyby a kolízie pri manévrovaní."],"h2-neuebedienung":["Prepnete sa na iný typ javiska. Čo sa vyžaduje?","Prevádzkové funkcie sa výrazne líšia.","Inštrukcie špecifické pre zariadenie pred nezávislým použitím.","Stačí si prečítať logo spoločnosti na zariadení.","Skúšobná jazda s už vysunutým košíkom bez návodu.","Samotná kvalifikácia nenahrádza poučenie o konkrétnom type zariadenia."],"h2-steckanschluss":["Čo by ste mali skontrolovať pred pripojením nabíjačky?","Elektrickú zdvíhaciu pracovnú plošinu je potrebné nabiť.","Použite akúkoľvek zásuvku bez ohľadu na stav a poistku.","Skontrolujte vhodné pripojenie a nepoškodený kábel podľa pokynov výrobcu.","Počas nabíjania pravidelne vyťahujte zástrčku zo zásuvky.","Vhodné a neporušené elektrické spojenia chránia pred úrazom elektrickým prúdom a požiarom."],"h2-absperrpersonal":["Počas zdvíhacích prác vstupuje osoba do ohradeného priestoru. čo to robíš?","Môžete vidieť osobu priamo pod pracovným košom.","Pokračujte v jazde, ak má osoba ochrannú prilbu.","Spustite nástroj v ich smere ako varovný signál.","Zastavte nebezpečný pohyb a nechajte priestor vyčistiť.","Závora nenahrádza pozorovanie nebezpečnej oblasti počas prevádzky."],"k2-arbeitsplanung":["Čo by mala zahŕňať príprava práce pred operáciou žeriavu?","Náklad, umiestnenie a trasa prepravy ešte nie sú koordinované.","Najprv zdvihnite najťažšie bremeno bez ďalšieho plánovania.","Na podlahe haly vyznačte len najkratšiu trasu.","Vopred si ujasnite nosnosť, popruhy, dráhu nákladu a nebezpečnú oblasť.","Plánovaný pohyb žeriava si vyžaduje vhodnú manipuláciu s bremenom, bezpečné trasy a koordinované ochranné opatrenia."],"k2-hakenposition":["Ako je žeriavový hák umiestnený nad nákladom pred zdvíhaním?","Upevňovacie body sú pod žeriavom.","Čo najviac kolmo nad ťažiskom podľa dorazu.","Posunutie ďaleko do strany, aby sa náklad naklonil rýchlejšie.","V každom prípade na vonkajšom okraji nákladu, bez ohľadu na ťažisko.","Vertikálne použitie sily a vhodné kotviace body znižujú pohyb do strán a nekontrolované pohyby."],"k2-hakengabel":["Nákladný hák vykazuje viditeľnú deformáciu. Čo platí?","Háčik vyzerá oproti svojmu obvyklému stavu ohnutý.","Pri ďalšom zaťažení ohnite deformáciu späť.","Zastavte prevádzku žeriavu a nechajte hák skontrolovať odborníkom.","Nasaďte len ľahké bremená a pokračujte v práci.","Deformácia môže ovplyvniť bezpečnosť háku; neoprávnené ďalšie použitie nie je povolené."],"k2-zugueberlast":["Bremeno je ťažšie, ako sa pôvodne predpokladalo. čo to robíš?","Počas prípravy vznikajú nové informácie o hmotnosti.","Vymeňte bezpečnostnú rezervu za rýchlejšie zdvíhanie.","Ignorujte hmotnosť nákladu jeho pripevnením k inému bodu.","Určite skutočné zaťaženie a znova skontrolujte limity zaťaženia.","Bezpečné zdvíhanie vyžaduje spoľahlivé údaje o zaťažení a dodržiavanie všetkých príslušných nosností."],"k2-arbeitskorb":["Dokáže obyčajný žeriavový hák ľahko prepraviť ľudí?","Človek sa chce dostať na vysoké pracovisko.","Nie, osobná doprava si vyžaduje povolené špeciálne zariadenia a opatrenia.","Áno, ak sa osoba drží závesného lana.","Áno, akonáhle sa zdvih vykoná obzvlášť pomaly.","Preprava osôb je povolená len za osobitných podmienok stanovených na tento účel."],"k2-bruecke":["Mostový žeriav sa pohybuje po spoločnej chodbe. čo je dôležité?","Zamestnanci zostávajú pod dopravnou trasou.","Jazdite s nákladom tesne nad hlavami zamestnancov.","Efektívne udržujte cestu nákladu a dopravnú oblasť voľnú a zabezpečenú.","Namiesto ďalších opatrení používajte iba výstražný klaksón.","Ohrozené osoby sa nesmú nachádzať pod zavesenými nákladmi ani na ich prepravnej ceste."],"k2-zweitekrane":["Dva žeriavy pracujú v prekrývajúcom sa priestore. Čo je potrebné?","Ramená alebo bremená by sa mohli navzájom zraziť.","Obaja žeriavnici pracujú súčasne bez predchádzajúcej dohody.","Pohyby sa zámerne zrýchľujú, aby sa vyhli križovatkám.","Koordinovať operácie a prijať vhodné opatrenia na predchádzanie vzájomným hrozbám.","Prekrývajúce sa pracovné oblasti si vyžadujú koordinovanú organizáciu prevádzky a vhodné bezpečnostné opatrenia."],"k2-pruefbuch":["Aký význam má povinná opakovaná prehliadka žeriavu?","Stroj je pravidelne využívaný v prevádzkach.","Prevádzkovú kontrolu dopĺňa o predpísané odborné vyšetrenie.","Trvalo nahrádza akúkoľvek vizuálnu kontrolu pred začatím práce.","Vyžaduje sa iba po havárii.","Opakujúce sa inšpekcie a priebežné prevádzkové kontroly majú rôzne úlohy."],"k2-absetzflaeche":["Zamýšľaná plocha umiestnenia je nerovnomerná. ako sa správaš?","Náklad by sa mohol pri umiestnení prevrátiť.","Položte náklad na jeden roh a nechajte ho visieť nezmenený.","Pripravte vhodné, nosné a stabilné podklady alebo povrchy.","Pri spúšťaní umiestnite pod náklad jednu osobu.","Priestory na umiestnenie musia bezpečne podopierať bremeno a zabraňovať nebezpečným prevráteniu alebo pohybu."],"k2-anfahrbereich":["Predtým, ako sa žeriav začne pohybovať, je v oblasti pohybu jedna osoba. čo to robíš?","Trasa je zablokovaná osobou.","Krátkou skúšobnou jazdou odtlačte osobu nabok.","Vyrazte pomocou samotného koncového spínača bez vizuálnej kontroly.","Pohyb začnite až vtedy, keď je nebezpečná oblasť voľná a bezpečná.","Jazdné a otočné pohyby nesmú ohrozovať osoby."],"k2-schlaffseil":["Prečo by sa lano zdviháka nemalo nekontrolovateľne uvoľniť, keď je odložené?","Náklad je zapnutý, hák je spustený ďalej.","Aby sa lano a háky nezasekli alebo nevystavili nekontrolovanému zaťaženiu.","Aby potom bolo možné náklad bočne ťahať lanom.","Aby sa popruhy oddelili od háku.","Nekontrolované vedenie káblov môže viesť k zapleteniu a nebezpečným pohybom bremena."],"k2-pendel":["Prepravovaný náklad sa začne kývať. čo je správne?","Náklad sa pohybuje bočne viac, ako bolo plánované.","Kompenzujte to rýchlymi protipohybmi a plnou rýchlosťou.","Kontrolovane znížte pohyby a upokojte dochádzanie bez ľudí v nebezpečnej oblasti.","Uchopte hojdaciu záťaž holými rukami.","Oscilujúce zaťaženie môže ovplyvniť ľudí a zariadenia; pokojné pohyby znižujú riziko."],"k2-funkakku":["Rádiové ovládanie žeriavu má slabú batériu. Čo platí?","Pri zdvíhaní by sa spojenie mohlo prerušiť.","Rýchlo zdvihnite bremeno skôr, ako ovládač zlyhá.","Ak dôjde k strate spojenia, presuňte bremeno potiahnutím za popruh.","Pred použitím zaistite spoľahlivé pripojenie ovládania.","Predpokladom riadených pohybov žeriavu je spoľahlivé ovládanie a komunikácia."],"k2-mehrereanschlaeger":["Dve osoby súčasne dávajú operátorovi žeriavu rôzne signály. čo je správne?","Znaky si navzájom odporujú.","Prerušte pohyb a vyjasnite si jasnú zodpovednosť.","Uprednostnite znamenie osoby, ktorá je vzdialenejšia.","Pokračujte v pohybe podľa vlastného pocitu.","Žeriavníci potrebujú jasnú a jednoznačnú komunikáciu, najmä keď sú trasy nákladu neprehľadné."],"k2-endabschaltung":["Prečo by sa koncový spínač nemal zneužiť ako normálne obmedzenie zdvihu?","Bremeno sa často presúva až na maximálnu zdvíhaciu vzdialenosť.","Koncové spínače vo všeobecnosti umožňujú rýchlejšie zdvíhanie bez viditeľnosti.","Koncové spínače sú bezpečnostné zariadenia a nenahrádzajú riadenú prevádzku.","Pri každom údere by mali dostať čo najväčší úder.","Bezpečnostné zariadenia slúžia na ochranu pred nebezpečenstvami a nesmú sa nadmerne používať podľa plánu."],"k2-wetterbeobachtung":["Vietor pri veľkom plošnom zaťažení výrazne narastá. Čo sa vyžaduje?","Veľká plocha komponentov pôsobí ako plachta.","Náklad vždy zdvíhajte vyššie, aby mal vietor menší účinok.","Vymeňte popruhy za tenšie.","Posúďte limity vetra a prevádzkové limity av prípade potreby upravte zdvíhanie.","Vietor môže vytvárať značné dodatočné sily a kyvadlové pohyby, najmä pri veľkoplošných zaťaženiach."],"k2-ortswechsel":["Čo je dôležité pri presúvaní mobilného žeriavu na nové miesto?","Menia sa podmienky podložia a podpory.","Pred opätovným zdvihnutím nákladu skontrolujte umiestnenie stojana a podperu.","Použiť nastavenia z predchádzajúceho umiestnenia bez kontroly.","Počas zdvíhania nechajte znovu nastaviť podperu.","Každé miesto inštalácie môže mať rôzne podmienky zaťaženia zeme a podpery."],"k2-betriebsbereich":["Na druhej strane ulice má fungovať žeriav. Čo je potrebné objasniť?","Tretie osoby by sa mohli dostať do nebezpečnej oblasti.","Cestu zabezpečte iba výstražnou húkačkou.","Požadované uzamknutia, hlasovanie a ochranné opatrenia pred centrom.","Zdvihnite náklad nad vozidlá čo najrýchlejšie bez toho, aby ste ho zaistili.","Bezpečné vedenie premávky zabraňuje neprimeranému riziku pre tretie osoby spôsobené pohybmi bremien a žeriavov."],"k2-hochheben":["Po skúšobnom zdvihu visí náklad zreteľne nakrivo. čo je správne?","Zameranie bolo zrejme nesprávne posúdené.","Pokračujte v zdvíhaní, aby sa nerovnováha sama napravila.","Požiadajte jednu osobu, aby ťahala opreté bremeno.","Bezpečne zložte náklad a znova skontrolujte pripevnenie a ťažisko.","Skúšobný zdvih sa používa na zistenie nesprávneho pripevnenia a nestabilných polôh nákladu pred prepravou."],"k2-schwebelast":["Môžete nechať zdvihnutý náklad visieť bez dozoru?","Smena sa končí, ale náklad je stále na háku.","Nie, bezpečne spustite bremeno a správne zaistite žeriav.","Áno, ak je žeriav zablokovaný proti pohybu.","Áno, pokiaľ je na zemi výstražné znamenie.","V zásade by sa zavesené bremená nemali nechávať bez dozoru."],"k2-mitnahme":["Kolega sa chce povoziť na žeriave. Čo platí?","Náklad by sa mal prepraviť do vyššieho bodu.","Jazda je povolená, ak má kolega na hlave prilbu.","Osoby sa nesmú prepravovať na normálnych nákladoch ani sa k nim pripájať.","Jazda je povolená vždy, pokiaľ je žeriavnik známy.","Prevážanie osôb spolu s nákladmi predstavuje značné riziko pádu a pomliaždenia."],"k2-warnsignal":["Funkčný výstražný systém na žeriave zlyhá. čo je správne?","Varovanie pred rozjazdom už nie je možné.","Ignorujte systém, keď motor beží.","Výstrahu natrvalo vymeňte poklepaním na kryt.","Nahláste poruchu súvisiacu s bezpečnosťou a prerušte prevádzku podľa pokynov.","Požadované výstražné zariadenia musia byť funkčné, aby boli ľudia včas chránení."],"k2-schneekante":["Na zamrznutom nerovnom teréne je potrebné podoprieť mobilný žeriav. Čo platí?","Pri roztápaní môže pôda stratiť svoju únosnosť.","Posúďte nosnosť a podpornú situáciu v skutočných podmienkach.","Zamrznutá zem má vždy akúkoľvek únosnosť.","Podpery položte iba na malé kamene.","Teplota, vlhkosť a štruktúra podložia ovplyvňujú nosnosť miest žeriavov."],"k2-laufkatze":["Vozík sa pohybuje smerom k prekážke. ako sa správaš?","V oblasti jazdy sa nachádza predmet.","Pomaly odtláčajte predmet s nákladom.","Zastavte pohyb včas a nechajte prekážku bezpečne odstrániť.","Prejdite okolo prekážky zvýšenou rýchlosťou.","Pohyby žeriavu musia byť vedené tak, aby nedochádzalo ku kolízii s prekážkami."],"k2-anschlagaufnahme":["Náklad by ste mali zdvihnúť pomocou neoznačeného oka. čo je správne?","Očko mohlo byť určené len na montáž krytu.","Každé očko je vhodné pre plné zaťaženie žeriavom.","Očko zaťažujte len dvoma osobami súčasne.","Pred použitím si overte nosnosť a vhodnosť kotviaceho bodu.","Nie každé existujúce oko je stabilným upevňovacím bodom pre bremená žeriavu."],"l2-seilbruch":["Drôtené lano zobrazuje niekoľko zlomených jednotlivých drôtov. čo je správne?","Miesta zlomu sú v oblasti nosného lana.","Zdvíhacie zariadenie ďalej nepoužívajte a nechajte si ho odborne posúdiť.","Ohnite konce drôtu späť holými rukami.","Pokračujte v používaní lana, ak je zaťaženie obzvlášť ľahké.","Prerušenia drôtu môžu byť kritériom vyradenia; Poškodené laná treba odborne posúdiť."],"l2-schaekel":["Čo je rozhodujúce pri použití okovu?","Okov spája popruh a náklad.","Nahraďte skrutku akýmkoľvek klincom.","Skontrolujte vhodnú nosnosť, nepoškodený stav a správne skrutky.","Odhadnite nosnosť podľa farby.","Okovy musia byť primerane dimenzované, musia byť použité úplne a v zamýšľanom smere zaťaženia."],"l2-tragfaehigkeit":["Čo musíte zvážiť pri použití viacerých prameňov?","Pramene prebiehajú pod uhlom k vertikále.","Jednoducho spočítajte nosnosť každého prameňa podľa želania.","Náklad zaveste len na najľahší prameň.","Zvážte nosnosť celého typu kotvy a uholníka.","Uhol sklonu a efektívny počet prameňov výrazne ovplyvňujú prípustné zaťaženie."],"l2-schweissnaht":["Môže byť improvizovaný kotviaci bod privarený k bremenu?","Pre náklad nie sú určené žiadne vhodné miesta na vyzdvihnutie.","Používajte iba správne navrhnuté a schválené kotviace body.","Akýkoľvek zvar stačí bez skúšania.","Otvorom v plechu prestrčte háčik.","Musí sa preukázať, že kotviace body sú vhodné pre sily spojené so zdvíhaním."],"l2-einseitig":["Náklad je na jednej strane výrazne ťažší. Ako na to idete?","Ťažisko leží mimo geometrického stredu.","Nechajte všetky pramene rovnako dlhé bez ohľadu na ťažisko.","Určite ťažisko a podľa toho upravte polohu.","Najprv zdvihnite náklad do plnej výšky zdvihu.","Ak je ťažisko mimo stredu, bremená sa môžu neočakávane prevrátiť alebo môžu byť jednotlivé pramene preťažené."],"l2-kettenriss":["Čo platí pre retiazku s viditeľnými prasklinami?","V jednom z článkov reťaze je prasklina.","Označte trhlinu farbou a zdvihnite ju bez zmeny.","Omotajte odkaz drôtom a znova ho použite.","Ihneď odstráňte reťaz a informujte zodpovednú osobu.","Trhliny v článkoch nosnej reťaze predstavujú poškodenie z hľadiska bezpečnosti a vyžadujú vyradenie z prevádzky."],"l2-lastfuehrung":["Ako prenesiete veľký náklad, keď hrozí rotácia?","Náklad sa môže počas zdvíhania kývať nabok.","Používajte vhodné navádzacie zariadenia a bezpečnú vzdialenosť.","Počas jazdy držte náklad priamo medzi rukami.","Vstúpte pod záťaž a zarovnajte ju zospodu.","Vedenie nákladu nesmie spôsobiť, že sa ruky alebo telá dostanú do nebezpečnej zóny."],"l2-schnueren":["Čo je dôležité pri zapínaní šnúrok?","Popruh je vedený okolo komponentu.","Predpokladajme rovnakú nosnosť ako akýkoľvek iný typ kotvy.","Dodržujte vhodnosť typu nástavca a prípustné zaťaženie podľa označenia.","Pritiahnite závesné zariadenie v ľubovoľnom rozsahu k sebe bez kontroly.","Typ šnurovacieho nástavca môže zmeniť prípustnú nosnosť a musí sa správne používať."],"l2-winkelmesser":["Prečo nemôžete ignorovať plochý uhol prameňa?","Dve závesné šnúry vedú takmer vodorovne k nákladu.","Plochý uhol automaticky zosilní prameň.","Záťaž je vždy rozložená rovnomerne bez ohľadu na uhol.","Vysoké sily prameňov môžu prekročiť prípustnú nosnosť.","Keď sa uhol k vertikále zväčšuje, zvyšuje sa napätie na prameňoch."],"l2-heisse-last":["Čo je potrebné skontrolovať na horúce zaťaženie?","Oceľová časť bola nedávno tepelne spracovaná.","Dodržujte teplotné limity popruhov a vhodný výber.","Každý textilný záves znesie akúkoľvek teplotu.","Na označení nezáleží, keď je horúco.","Teplota môže ovplyvniť prípustnú nosnosť popruhov."],"l2-abstand":["Môžete dať prsty pod náklad pri ukladaní?","Náklad by mal dopadnúť na povrch s milimetrovou presnosťou.","Áno, ak nosíte pracovné rukavice.","Nie, udržujte si odstup a používajte vhodné pomôcky.","Áno, ak je pohyb žeriava obzvlášť pomalý.","Časti tela medzi nákladom a základňou sa môžu zachytiť."],"l2-verbindung":["Spojovací článok retiazky nie je zablokovaný. Čo platí?","Chýba zapínanie.","Použite závoru bez zámku, keď sa nikto nepozerá.","Utesnite prvok lepiacou páskou.","Neudierajte, kým nie je upevňovací prvok správne zaistený.","Spojovacie prvky musia byť zaistené úplne a v súlade s ich prevedením."],"l2-lasthaken":["Čo kontrolujete pri zavesení na hák žeriavu?","Do háku by sa malo zaviesť niekoľko popruhov.","Zabezpečte bezpečné uchytenie a vhodnosť háčikov a zavesenia.","Umiestnite popruhy na špičku háku.","Vymeňte hákový zámok za káblovú pásku.","Sila musí byť aplikovaná podľa plánu v určených oblastiach."],"l2-fasern":["Zdvíhací popruh vykazuje silné zdrsnenie a poškodenie vlákna. čo je správne?","Nosné vlákna sú viditeľne poškodené.","Poškodenie zakryte ďalším uzlom.","Oddeľte zdvíhací popruh a nechajte ho skontrolovať odborníkom.","Potom zdvíhajte bremeno rýchlejšie.","Poškodené nosné vlákna môžu výrazne znížiť nosnosť zdvíhacieho popruhu."],"l2-anheben":["Čo platí hneď po prvom centimetri zdvihnutia?","Náklad sa práve zdvíha zo základne.","Vytiahnite náklad do jeho plnej výšky bez kontroly.","Skontrolujte pod bremenom, či sú popruhy napnuté.","Skontrolujte polohu dorazu, rovnováhu a pohybové správanie.","Kontrolovaný skúšobný zdvih zviditeľní možné nestability pred ďalšou prepravou."],"l2-lastgewichte":["Hmotnosť nákladu nie je známa. čo je správne?","Komponent nemá označenie hmotnosti.","Pred výberom popruhov určite nosnosť.","Odhadnite hmotnosť na základe farby nákladu.","Použite akýkoľvek popruh s dvojitou dĺžkou.","Bez známej alebo spoľahlivo určenej hmotnosti nie je možné s istotou skontrolovať vhodnosť popruhov."],"l2-lose-teile":["Na náklade, ktorý sa má zdvíhať, sú voľné nástroje. čo to robíš?","Náradie by pri zdvíhaní mohlo spadnúť.","Pri šoférovaní držte náradie jednou rukou.","Pred zdvíhaním odstráňte alebo účinne zaistite voľné predmety.","Náklad zdvihnite o niečo rýchlejšie, aby sa nič nešmýkalo.","Voľné predmety môžu spadnúť a ohroziť ľudí v okolí."],"l2-wind":["Pri silnom vetre je pripevnený veľký náklad. Čo platí?","Komponent ponúka vetru veľkú plochu na útok.","Zdvihnite bremeno bez ohľadu na kývavé pohyby.","Ďalšie osoby by mali náklad držať priamo.","Posúďte veterné podmienky a zdržte sa zdvíhania, ak nie je situácia bezpečná.","Sily vetra môžu ovplyvniť vedenie nákladu a stabilitu počas prepravy."],"l2-unterlage":["Prečo sú pri odvykaní dôležité vhodné doklady?","Okrúhly náklad by sa odkotúľal po zemi.","Náklad pevne položte a v prípade potreby ho zaistite proti samovoľnému pohybu.","Nechajte náklad stáť priamo na popruhoch.","Dokumenty zatlačte pod náklad až po ich odložení.","Vhodné podpery zabraňujú prevráteniu a nechceným pohybom pri usadzovaní."],"l2-transportweg":["Čo je potrebné skoordinovať pred prepravou nákladu?","Náklad sa presúva cez niekoľko pracovných oblastí.","Len očakávané trvanie hubu.","Bezpečná cesta nákladu, komunikácia a potrebné bariéry.","Jedna osoba by mala ukázať cestu pod nákladom.","Preprava nákladov si vyžaduje bezpečné dopravné trasy a jasnú koordináciu."],"l2-schutzschlauch":["Na čo si dať pozor pri používaní popruhov s ochrannou hadicou?","Pás leží na drsnom okraji.","Akákoľvek tenká tkanina nahrádza vhodnú ochranu hrán.","Ochranná hadica odstraňuje akýkoľvek povolený limit zaťaženia.","Vyberte ochranné prostriedky podľa vhodnosti a požiadaviek aplikácie.","Ochranné prostriedky musia zodpovedať materiálu, okraju a predpokladanému zaťaženiu."],"l2-reinigung":["Zdvíhací popruh bol kontaminovaný neznámou chemikáliou. čo je správne?","Páska sa už nedá jednoznačne posúdiť.","Prestaňte používať a odborne si ujasnite kompatibilitu alebo stav.","Očistite akýmkoľvek rozpúšťadlom a ihneď pokračujte v zdvíhaní.","Ignorujte chemikáliu, kým je páska suchá.","Chemikálie môžu ovplyvniť pevnosť textilných popruhov."],"l2-aufhaengung":["Čo kontrolujete, či na závesnom článku nie sú viaceré vlákna?","Dva pramene sú umiestnené spolu v suspenzii.","Prameň sa môže ľubovoľne pohybovať do špičky háčika.","Všetky spojovacie prvky musia byť vhodné a usporiadané podľa určenia.","Pre malé zaťaženie je možné použiť krúžok s trhlinou.","Dorazové a spojovacie prvky musia byť nosné a správne usporiadané."],"l2-einweiserrolle":["Čo platí, ak útočník a operátor žeriavu nemajú priamy výhľad?","Nosič blokuje výhľad na bod výpadu.","Koordinujte tak, že zavoláte viacerým ľuďom bez zodpovednosti.","Presuňte náklad na základe hluku bez pokynov.","Zorganizujte jasnú a bezpečnú komunikáciu a zastavte ju, ak je nejasná.","Nedostatok viditeľnosti musí byť kompenzovaný efektívnou koordináciou a bezpečnou komunikáciou."],"l2-ausserbetrieb":["Poškodený popruh bol vyriešený. Čo je ešte dôležité?","Zostáva voľne prístupná spolu so zdrojmi pripravenými na použitie.","Zabezpečte proti ďalšiemu náhodnému použitiu a informujte zodpovednú osobu.","Vráťte výrobok neoznačený do inventára.","Znova ho použite len pri prenášaní obzvlášť ľahkého nákladu.","Vyradené viazacie prostriedky musia byť pred ďalším použitím spoľahlivo chránené."],"b2-schwenkradius":["Prečo je polomer otáčania zadnej časti rýpadla kritický?","Chvost sa pohybuje cez obmedzenú pracovnú oblasť.","Tretie osoby môžu byť zachytené výkyvnou nadstavbou.","Polomer otáčania nemá žiadny vplyv na ľudí v blízkosti stroja.","Zadná časť sa pohybuje vždy len v smere jazdy.","Pri otáčaní vzniká nebezpečná oblasť aj za strojom."],"b2-verkehrseinweiser":["Ako je zabezpečený jazdný pohyb pri zníženej viditeľnosti?","Bager musí manévrovať za prekážkou.","Jazdite bez toho, aby ste videli signály signalizátora.","Ak je to potrebné, zorganizujte vhodné inštrukcie s jasnou komunikáciou.","Cúvanie zaistite iba raz zatrúbením.","Neprehľadné trasy si vyžadujú účinné opatrenia na zabránenie kolíziám a zachyteniu."],"b2-standplatz":["Čo platí pre stojan bagra na svahu?","Podlaha je naklonená a môže byť šmykľavá.","Stroj sa môže vysunúť tak ďaleko, ako chce pri akomkoľvek sklone.","Rýpadlo vždy postavte na voľnú vrstvu zeme.","Pred použitím skontrolujte stabilitu a prevádzkové limity stroja.","Významný vplyv na stabilitu má sklon svahu a podložie."],"b2-oberleitung":["Prečo je potrebné plánovať vzdialenosť výložníka od elektrického vedenia?","Rameno sa môže pri otáčaní priblížiť ku káblu.","Elektrický preskok je možný aj bez priameho kontaktu.","Elektrinu môže viesť iba vedro, nie výložník.","So suchou pôdou je každá vzdialenosť automaticky bezpečná.","Pred priblížením sa k elektrickým systémom si musíte ujasniť limity použitia a ochranné vzdialenosti."],"b2-fremdperson":["Okoloidúci vchádza na stavenisko v oblasti ryžovania. čo je správne?","Osoba zrazu stojí blízko lopaty rýpadla.","Zdvihnite lopatu a prehoďte ju nad osobu.","Okamžite zastavte pohyb a nechajte oblasť vyčistiť.","Len ďalej sledujte osobu z bočného okna.","Osoby v nebezpečnej oblasti nesmú byť ohrozené pracovnými pohybmi."],"b2-parkstellung":["Ako je zabezpečený zemný stroj po ukončení práce?","Bager zostáva na stavenisku bez dozoru.","Den Löffel v Kopfhöhe stehen lassen.","Den Motor unbeaufsichtigt durchlaufen lassen.","Odložte pracovný prostriedok, zabezpečte stroj a zabráňte neoprávnenému použitiu.","Správne parkovanie znižuje náhodný pohyb a neoprávnený prístup."],"b2-eigenlast":["Prečo sú limity zariadení rozhodujúce pri zdvíhaní pomocou rýpadla?","Na výložník je potrebné zdvihnúť ťažký náklad.","V opačnom prípade môže dôjsť k prekročeniu stability a prípustnej nosnosti.","Akýkoľvek stroj môže zdvihnúť akýkoľvek náklad, pokiaľ sa lyžica zmestí.","Riziko určuje iba dĺžka závesného lana.","Informácie o zdvíhaní a nosnosti závisia od vybavenia a situácie použitia."],"b2-untergrundhohlraum":["Podlaha nad starým suterénom môže byť dutá. čo to robíš?","Mali by ste zaviesť bager do oblasti.","Prejdite bod s maximálnou dynamikou.","Pred jazdou si ujasnite nosnosť a možné dutiny.","Jednoducho položte na povrch veľkú záťaž.","Dutiny sa môžu pod váhou stroja zrútiť a spôsobiť pád stroja."],"b2-feuchtigkeit":["Po silnom daždi nábrežie zmäkne. čo je správne?","V blízkosti okraja násypu pracuje bager.","Presuňte stroj bližšie k okraju, aby ste zvýšili dosah.","Ignorujte zmeny až do konca zmeny.","Prehodnoťte pôdne a stabilizačné podmienky.","Prenikanie vlhkosti môže zmeniť únosnosť a stabilitu násypov."],"b2-bodenprobe":["Prečo je potrebné pred výkopom skontrolovať plány potrubia?","Pod plánovaným výkopom by mohli viesť káble.","Aby bolo možné identifikovať línie a naplánovať vhodné bezpečnostné opatrenia.","Aby sa výkopové práce mohli vykonávať rýchlejšie, nezávisle od systémov tretích strán.","Pretože stroje sa nikdy nesmú používať v blízkosti káblov.","Podzemné prívodné vedenia vyžadujú spoľahlivé objasnenie polohy pred výkopovými prácami."],"b2-maschinenzugang":["Čo platí pri nastupovaní a vystupovaní zo zemného stroja?","Stroj je na nerovnom teréne.","Vysuňte hydraulické vedenie z kabíny.","Používajte určené kroky a zaistite bezpečný postoj.","Počas chodu stroja skočte na otočné rameno.","Bezpečné stúpanie a vhodné miesta na zastavenie znižujú riziko pádu a rozdrvenia."],"b2-kupplung":["Ako skontrolujete nový bager po inštalácii?","Lyžica sa pripája pomocou rýchlospojky.","Lyžicu posúďte len vizuálne z väčšej vzdialenosti.","Vstúpte priamo pod zdvihnutú lyžicu.","Zabezpečte správne uzamknutie a predpísané kontrolné kroky.","Nesprávne zaistené nadstavce sa môžu uvoľniť a ohroziť ľudí."],"b2-hydraulikwartung":["Prečo nie je dovolené otvárať hydraulické vedenia pod tlakom?","Je potrebné vymeniť hadicu.","Unikajúca kvapalina môže spôsobiť vážne zranenia v dôsledku vysokého tlaku.","Tlak vždy zabraňuje úniku oleja.","Otvorenú líniu je možné bezpečne kontrolovať rukami.","Vysokotlaková kvapalina môže preniknúť do tkaniva a vyžaduje bezpečné uvoľnenie tlaku."],"b2-fahrweg":["Musíte prejsť cez dočasný stavebný most. čo to kontroluješ?","Most je navrhnutý len pre určité zaťaženie.","Či sa farba mostíka zhoduje so strojom.","Nosnosť a vhodnosť pre hmotnosť a rozmery stroja.","Len či už po moste jazdilo ľahké auto.","Dočasné stavby možno použiť len v rámci ich preukázanej únosnosti."],"b2-baggertransport":["Čo je dôležité pri preprave bagra na podvalníku?","Stroj je odvezený na ďalšie stavenisko.","Pracovné náradie nechajte voľne vyčnievať cez okraj.","Počas jazdy nechajte dvere kabíny otvorené.","Zaistite stroj podľa prepravných špecifikácií a skontrolujte nakladacie zariadenie.","Transportné zámky a vhodné nakladacie zariadenia zabraňujú pošmyknutiu a pádu."],"b2-schaufelfuellung":["Prečo kolesový nakladač nemôže jazdiť rýchlo s vysoko zdvihnutou lyžicou?","Náklad je ťažký a terén je nerovný.","Vysoké ťažisko môže zvýšiť riziko prevrátenia a problémov s viditeľnosťou.","Lopata sa pri vysokých rýchlostiach automaticky stabilizuje.","Výška lopaty nie je dôležitá pre stabilitu.","Zvýšené ťažisko zvyčajne zhoršuje stabilitu pri jazde a v zákrutách."],"b2-fussgaenger":["Ako sa správate pri manévrovaní vedľa chodcov?","Prístup na stavenisko je tiež chodníkom.","Pomocou lopaty nasmerujte chodcov na stranu.","Jazdný pohyb vykonávajte len vtedy, keď je oblasť bezpečne voľná a ovládateľná.","Stačí raz zatrúbiť a jazdiť pomaly bez viditeľnosti.","Prevádzka vozidiel a cestujúcich musí byť účinne oddelená alebo bezpečne koordinovaná."],"b2-ueberlastwarnung":["Pri zdvíhaní stroj hlási preťaženie. čo to robíš?","Zdvihnuté bremeno dosahuje povolené limity.","Vypnite varovanie a pokračujte v jeho zvyšovaní bez zmeny.","Počas chodu stroja náhle utiahnite bremeno.","Zastavte nebezpečné pohyby a bezpečne opravte situáciu s nákladom.","Varovania pri preťažení indikujú možné prekročenie limitov a riziká stability."],"b2-wasserleitung":["Pri kopaní je odkrytá neznáma rúra. Čo platí?","V stavebných plánoch nie je vyznačená čiara.","Zastavte prácu v postihnutej oblasti a nechajte si linku odborne identifikovať.","Skúste posunúť linku pomocou lopaty rýpadla.","Pokračujte v kopaní priamo pod čiarou bez kontroly.","Neznáme vedenia môžu spôsobiť ohrozenie elektrickým prúdom, plynom alebo vodou."],"b2-hangefahrt":["Ako sa riadi bager v strmom svahu?","Plánovaná trasa vedie po svahu.","Jazdite po svahu bez ohľadu na limity výrobcu.","Dodržujte povolený sklon a predpísaný spôsob jazdy stroja.","Vyklopte výložník ďaleko, aby ste vozidlo vyvážili.","Prípustný sklon závisí od stroja, povrchu a údajov výrobcu."],"b2-schlechtebeleuchtung":["Pri práci v tmavej jame je viditeľnosť nedostatočná. čo je správne?","Ľudí a prekážky takmer nevidíte.","Zvýšte rýchlosť kopania na rýchle dokončenie operácie.","Svetlá nepoužívajte, keď je motor v chode.","Zastavte prácu, kým nebudú nebezpečné oblasti dostatočne viditeľné.","Pre kontrolované pohyby stroja je potrebná bezpečná viditeľnosť jazdných a pracovných oblastí."],"b2-kettenverschleiss":["Pri každodennej kontrole je spozorovaná poškodená húsenková dráha. čo to robíš?","Reťazové spojenie vykazuje jasné poškodenie.","Stroj ďalej nekontrolovane nepoužívajte a nahláste akékoľvek poškodenie.","Pokračujte v jazde vysokou rýchlosťou, aby sa reťaz vyrovnala.","Pokračujte v práci len na mäkkom podklade bez kontroly.","Poškodenie pohonu môže zhoršiť ovládateľnosť a stabilitu."],"b2-ladearbeiten":["Naložíte nákladné auto s bagrom. čo je dôležité?","Vodič kamiónu sa zdržiava v blízkosti nakladacej plochy.","Prehoďte vedro cez nechránenú kabínu vodiča.","Zabráňte ľuďom zdržiavať sa v nebezpečnej oblasti a koordinujte procesy.","Spustite načítanie bez komunikácie s vodičom.","Pri nakladaní hrozí nebezpečenstvo pádu materiálu a kývavých pohybov."],"b2-arbeitsunterbrechung":["Výkopové práce prerušíte kvôli porade. Čo platí?","Stroj by mal stáť niekoľko minút bez obsluhy.","Zdvihnutú lopatu nechajte ako značku.","Nechajte stroj bez dozoru so zapnutým trakčným pohonom.","Náradie bezpečne odstavte a stroj zaistite proti neúmyselnému použitiu.","Dokonca aj krátke prerušenia vyžadujú bezpečný stav stroja."],"b2-rollmaterial":["Voľný materiál môže pri preprave kolesovým nakladačom spadnúť. čo je správne?","Nakladač jazdí blízko zamestnancov.","Bezpečne zdvihnite náklad a zvoľte bezpečný štýl jazdy s vhodnou polohou lopaty.","Zdvihnite lopatu čo najvyššie, aby okolie malo voľný výhľad.","Zdvihnite náklad bez obmedzenia plnenia vedra.","Voľný náklad, vysoká poloha lopaty a zlá viditeľnosť môžu ohroziť ľudí a premávku."]};
